**提示 1：** 考虑每次操作会对当前的分数和有啥影响。

**提示 2：** 交换相邻两次操作会如何改变这个结果？

最小值和最大值是完全对称的，只要你把所有的 $x$ 换成 $n+1-x$ 就求出来了。我们下面求最大值。

假设初始情况下分数和为 $V$ ，评论者数量为 $cnt$ ，如果评论者的类型是 S ，则对结果进行 $+k$ 操作；如果类型是 D，则将 $V$ 更新为 $\max(V+1,\min(V+n,cnt\times k))$ 。称 $\max(B,\min(A,x))$ 操作为 $clip(x,A,B)$ 。

假设某两个操作相邻，则：

- 如果两个评论者都是 S 类型的，则不会改变最终结果。

- 如果是 S, D 类型的，设数值分别为 $x_1,x_2$ ，两种操作的方式的结果分别是 $clip((cnt+1)\times x_2,x+x_1+1,x+x_2+n)$ 和 $clip(cnt\times x_2,x+1,x+n)+x_1=clip(cnt\times x_2+x_1,x+x_1+1,x+x_1+n)$ ，两者之间的大小关系只取决于 $x_1,x_2$ 的大小关系。

- 如果是两个 D 类型的，设数值分别为 $x_1,x_2$ ，也应当把小数值放前面（可以自行验证，直接用式子描述比较复杂，直观上是先把容易让数值变小的操作先做掉，后面的限制更小，且后面的数值更大在 $cnt$ 更大的时候效果更好）。

所以综上，只需把 $x$ 较大的操作放后面做就行。按照这点排序即可。而 $x$ 数值相同的任意调换顺序是不影响答案的。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()

    types = []
    score = []

    for _ in range(m):
        t, x = LI()
        types.append(1 if t == 'S' else 0)
        score.append(int(x))

    def solve():
        cnt = 0
        cur = 0
        for i in sorted(range(m), key=lambda x: score[x]):
            cnt += 1
            if types[i]: cur += score[i]
            else: cur = fmin(cur + n, fmax(cur + 1, score[i] * cnt))
        return cur / cnt

    mx = solve()

    for i in range(m):
        score[i] = n + 1 - score[i]

    mn = n + 1 - solve()

    print(f'{mn:.15f} {mx:.15f}')
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, k;
	cin >> n >> k;

	vector<pair<char, int>> readers(k);
	for (auto &[t, x]: readers) cin >> t >> x;

	sort(readers.begin(), readers.end(), [&] (pair<char, int> &x, pair<char, int> &y) {
		return x.second < y.second;
	});

	auto f = [&] () -> long double {
		long long tot = 0, cnt = 0;
		for (auto &[t, x]: readers) {
			cnt ++;
			if (t == 'S') tot += x;
			else tot = max(tot + 1, min(tot + n, cnt * x));
		}
		return (long double)tot / cnt;
	};

	auto mx = f();

	reverse(readers.begin(), readers.end());
	for (auto &[t, x]: readers) x = n + 1 - x;

	auto mn = f();
	mn = n + 1 - mn;

	cout << fixed << setprecision(15) << mn << ' ' << mx;

	return 0;
}
```

**提示 1：** DP ，如何找到转移区间？

右端点固定时，左端点越靠左，MEX 数值越大（单调不减）。

所以，考虑到第 $i$ 个位置截断的方案数是 $dp[i]$ ，则考虑最后一段的左端点，一定形成一个连续的区间，因此我们只需将这个区间内的总方案数转移到 $dp[i]$ 即可。

如何找到这个区间呢？我们可以维护 MEX 不超过 $x$ 的最小左端点，可以用一个数组，统计严格小于 $x$ 的元素出现了多少个，一旦有元素没有出现，这个位置就开始合法了。然后用 $x=r$ 和 $x=l-1$ 的两个端点即可确定。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, l, r = MII()
    nums = LII()
    r += 1

    mod = 998244353

    v1 = [0] * l
    v2 = [0] * r

    p1 = 0
    p2 = 0

    c1 = 0
    c2 = 0

    fen = FenwickTree(n + 1)
    fen.add(0, 1)

    for i in range(n):
        if nums[i] < l:
            if v1[nums[i]] == 0: c1 += 1
            v1[nums[i]] += 1

        if nums[i] < r:
            if v2[nums[i]] == 0: c2 += 1
            v2[nums[i]] += 1

        while p1 <= i and c1 == l:
            if nums[p1] < l:
                v1[nums[p1]] -= 1
                if v1[nums[p1]] == 0:
                    c1 -= 1
            p1 += 1

        while p2 <= i and c2 == r:
            if nums[p2] < r:
                v2[nums[p2]] -= 1
                if v2[nums[p2]] == 0:
                    c2 -= 1
            p2 += 1

        fen.add(i + 1, fen.rsum(p2, p1 - 1) % mod)

    print(fen.rsum(n, n))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, l, r, mod = 998244353;
	cin >> n >> l >> r;

	vector<int> nums(n);
	for (auto &x: nums) cin >> x;

	r ++;

	vector<int> v1(l, 0), v2(r, 0);
	int p1 = 0, p2 = 0;
	int c1 = 0, c2 = 0;

	atcoder::fenwick_tree<long long> fen(n + 1);
	fen.add(0, 1);

	for (int i = 0; i < n; i ++) {
		if (nums[i] < l) {
			if (!v1[nums[i]]) c1 ++;
			v1[nums[i]] ++;
		}

		if (nums[i] < r) {
			if (!v2[nums[i]]) c2 ++;
			v2[nums[i]] ++;
		}

		while (p1 <= i && c1 == l) {
			if (nums[p1] < l) {
				v1[nums[p1]] --;
				if (!v1[nums[p1]]) c1 --;
			}
			p1 ++;
		}

		while (p2 <= i && c2 == r) {
			if (nums[p2] < r) {
				v2[nums[p2]] --;
				if (!v2[nums[p2]]) c2 --;
			}
			p2 ++;
		}

		fen.add(i + 1, fen.sum(p2, p1) % mod);
	}

	cout << fen.sum(n, n + 1);

	return 0;
}
```

**提示 1：** 考虑不得不动的元素，以及其他元素为了使得这些元素能到目标位置需要做什么。

首先，如果一个元素在移动前和移动后既不在同一行，也不在同一列，那一定没办法达成。

否则，首先考虑那些行内需要移动的元素——它们的前后顺序不能变，因为同色的不能在同一个格子内，所以需要一开始就保持正确的顺序。

同列的元素的上下顺序也不能变，也需要一开始就满足从上到下升序。

同时，一个元素从一个位置移动到另一个位置的过程中，途径的那些不动的元素一定只能是另一个颜色的——不然没办法绕开来。这里可以用差分数组来更新（起点到终点的区间）。

那如果横着走或者竖着走都会经过这个格子，那就产生了矛盾了。所以还需要判这件事儿。

而在上述条件都满足的情况下，我们可以让异色的元素先让开位置，再把同色的在这一行排好，再把异色元素挪回来。每行的元素 / 每列的元素都可以这么解决。

时间复杂度为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    grid = [LGMI() for _ in range(n)]

    tag = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if grid[i][j] // n == i:
                tag[i][j] |= 1
            if grid[i][j] % n == j:
                tag[i][j] |= 2

            if tag[i][j] == 0:
                exit(print('No'))

    block_tag = [[0] * n for _ in range(n)]

    for i in range(n):
        cur = -1
        diff = [0] * n

        for j in range(n):
            if tag[i][j] == 1:
                if grid[i][j] < cur:
                    exit(print('No'))
                cur = grid[i][j]

                l, r = grid[i][j] % n, j
                if l > r: l, r = r, l
                diff[l + 1] += 1
                diff[r] -= 1

        for j in range(1, n):
            diff[j] += diff[j - 1]

        for j in range(n):
            if diff[j] and tag[i][j] == 3:
                block_tag[i][j] += 1

    for j in range(n):
        cur = -1
        diff = [0] * n

        for i in range(n):
            if tag[i][j] == 2:
                if grid[i][j] < cur:
                    exit(print('No'))
                cur = grid[i][j]

                l, r = grid[i][j] // n, i
                if l > r: l, r = r, l
                diff[l + 1] += 1
                diff[r] -= 1

        for i in range(1, n):
            diff[i] += diff[i - 1]

        for i in range(n):
            if diff[i] and tag[i][j] == 3:
                block_tag[i][j] += 1

    for i in range(n):
        for j in range(n):
            if block_tag[i][j] == 2:
                exit(print('No'))

    print('Yes')
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<vector<int>> grid(n, vector<int>(n));
	for (auto &x: grid) for (auto &y: x) cin >> y, y --;

	vector<vector<int>> tag(n, vector<int>(n, 0));

	for (int i = 0; i < n; i ++) {
		for (int j = 0; j < n; j ++) {
			if (grid[i][j] / n == i) tag[i][j] |= 1;
			if (grid[i][j] % n == j) tag[i][j] |= 2;
			if (!tag[i][j]) return cout << "No", 0;
		}
	}

	vector<vector<int>> block_tag(n, vector<int>(n, 0));

	for (int i = 0; i < n; i ++) {
		int cur = -1;
		vector<int> diff(n, 0);

		for (int j = 0; j < n; j ++) {
			if (tag[i][j] == 1) {
				if (grid[i][j] < cur) return cout << "No", 0;
				cur = grid[i][j];

				int l = grid[i][j] % n, r = j;
				if (l > r) swap(l, r);
				diff[l + 1] ++, diff[r] --;
			}
		}

		for (int j = 1; j < n; j ++) diff[j] += diff[j - 1];

		for (int j = 0; j < n; j ++) {
			if (diff[j] && tag[i][j] == 3) {
				block_tag[i][j] ++;
			}
		}
	}

	for (int j = 0; j < n; j ++) {
		int cur = 0;
		vector<int> diff(n, 0);

		for (int i = 0; i < n; i ++) {
			if (tag[i][j] == 2) {
				if (grid[i][j] < cur) return cout << "No", 0;
				cur = grid[i][j];

				int l = grid[i][j] / n, r = i;
				if (l > r) swap(l, r);
				diff[l + 1] ++, diff[r] --;
			}
		}

		for (int i = 1; i < n; i ++) diff[i] += diff[i - 1];

		for (int i = 0; i < n; i ++) {
			if (diff[i] && tag[i][j] == 3) {
				block_tag[i][j] ++;
			}
		}
	}

	for (auto &x: block_tag) for (auto &y: x) if (y == 2) return cout << "No", 0;

	cout << "Yes";

	return 0;
}
```

**提示 1：** 请看清楚数据范围，点数不会超过 $10^6$ 。

**提示 2：** 按层更新。

注意，这题的结点数并不会超过 $10^6$ 。

所以除非 $k=1$ ，这棵树的深度也最多就是 $\mathcal{O}(\log_k 10^6)$ 的量级。

那既然点数并不多，也就可以使用常规的数据结构了。

我们可以对于树上的每个结点维护这个结点到对应子树内的叶子的路径的最小权值和。每个结点只需考虑自己的子结点数值的更新情况即可。

而寻找最小的叶子也只需一层层来——找到包含最小叶子的第一个子树，不断往下找，找 $l$ 层即可。这件事儿相当于序列更新的时候求子结点第一个最小值的位置，因此维护一个 $k$ 个数形成的线段树即可。

接下来路径加 $w_i$ 如何更新呢？从叶子开始，一步步往上走，经历过的每一个结点都对子树中的所有叶子节点 $+w_i$ 。因为是一整棵子树做操作，所以无需使用懒更新线段树，直接打个大的标记就行。

设节点数量是 $V$ ，则时间复杂度为 $\mathcal{O}(V+n\log_k V\log k)\mathcal{O}(V+n\log V/\log k\times \log k)=\mathcal{O}(V+n\log V)$ 。（换底公式）

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    k, l, n = MII()
    ws = LII()

    if k == 1:
        print(sum(ws) * (l - 1))
    else:
        segs = []
        tags = []

        cur = 1

        for i in range(l - 1):
            segs.append([SegTree(fmin, inf, [0] * k) for _ in range(cur)])
            tags.append([0] * cur)
            cur *= k

        for w in ws:
            idx = 0

            for i in range(l - 1):
                v = segs[i][idx].all_prod()
                idx = idx * k + segs[i][idx].max_right(0, lambda x: x > v)

            delta = 0

            for i in range(l - 2, -1, -1):
                idx, pos = divmod(idx, k)
                old = segs[i][idx].all_prod()
                segs[i][idx].set(pos, segs[i][idx].get(pos) + w + delta)
                delta = segs[i][idx].all_prod() - old

        print(segs[0][0].all_prod())
```

C++ 做法如下——

```cpp []
long long op(long long x, long long y) {return min(x, y);}

long long e() {return 4e18;}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int k, l, n;
	cin >> k >> l >> n;

	vector<int> ws(n);
	for (auto &x: ws) cin >> x;

	if (k == 1) {
		long long total = 0;
		for (auto &x: ws) total += x;
		cout << total * (l - 1);
	}
	else {
		vector<vector<atcoder::segtree<long long, op, e>>> segs(l - 1);
		vector<vector<long long>> tags(l - 1);
		vector<long long> tmp(k, 0);

		int cur = 1;
		for (int i = 0; i < l - 1; i ++) {
			for (int j = 0; j < cur; j ++) {
				segs[i].push_back(atcoder::segtree<long long, op, e>(tmp));
				tags[i].push_back(0);
			}
			cur *= k;
		}

		for (auto &w: ws) {
			int idx = 0, pos;

			for (int i = 0; i < l - 1; i ++) {
				auto v = segs[i][idx].all_prod();
				idx = idx * k + segs[i][idx].max_right(0, [&] (long long x) {return x > v;});
			}

			long long delta = 0;

			for (int i = l - 2; i >= 0; i --) {
				pos = idx % k, idx /= k;
				long long old = segs[i][idx].all_prod();
				segs[i][idx].set(pos, segs[i][idx].get(pos) + w + delta);
				delta = segs[i][idx].all_prod() - old;
			}
		}

		cout << segs[0][0].all_prod();
	}

	return 0;
}
```

**提示 1：** 从共同点开始。

**提示 2：** 最短路，维护什么？

因为这题要求的东西是每个点到 $1$ 的问题，所以应该考虑公共部分—— $1$ 。也就是从 $1$ 为问题考虑的起点。

因为从 $1$ 出发，因此我们可以尝试从一个可以到达 $1$ 结点的位置出发，确定其余点能否走到 $1$ 结点。

这就很像一个最短路问题。我们只需维护从 $u$ 结点出发能到达 $1$ 的最晚出发时间 $f(u)$ 。则 $v$ 若使用一条 $u,h,t$ 的边经过 $u$ 到达结点 $1$ ，最晚的出发时间是 $\min(h, f(u))-t$ ，这件事儿就可以用来跑最短路了。

时间复杂度为 $\mathcal{O}(n+m\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()

    path = [[] for _ in range(n)]

    us = []
    vs = []
    ts = []
    hs = []

    for eid in range(m):
        u, v, t, h = MII()

        u -= 1
        v -= 1

        us.append(u)
        vs.append(v)
        ts.append(t)
        hs.append(h)

        path[u].append(eid)
        path[v].append(eid)

    inf = 2 * 10 ** 9

    latest_time = [-1] * n
    latest_time[0] = inf

    def f(x, y):
        return x * n + y

    pq = [f(-inf, 0)]

    while pq:
        d, u = divmod(heappop(pq), n)
        d = -d

        if latest_time[u] == d:
            for eid in path[u]:
                v = us[eid] ^ vs[eid] ^ u
                nd = fmin(d, hs[eid]) - ts[eid]

                if nd > latest_time[v]:
                    latest_time[v] = nd
                    heappush(pq, f(-latest_time[v], v))

    print(''.join('1' if x >= 0 else '0' for x in latest_time))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<vector<array<int, 3>>> path(n);

	while (m --) {
		int u, v, t, h;
		cin >> u >> v >> t >> h;
		u --, v --;
		path[u].push_back({v, t, h});
		path[v].push_back({u, t, h});
	}

	vector<int> latest_time(n, -1);
	latest_time[0] = (int)1e9;

	priority_queue<pair<int, int>> pq;
	pq.push({latest_time[0], 0});

	while (!pq.empty()) {
		auto [d, u] = pq.top(); pq.pop();
		if (latest_time[u] == d) {
			for (auto &[v, t, h]: path[u]) {
				int nd = min(d, h) - t;
				if (nd > latest_time[v]) {
					latest_time[v] = nd;
					pq.push({nd, v});
				}
			}
		}
	}

	for (auto &x: latest_time) cout << (x >= 0);

	return 0;
}
```

**提示 1：** 只需找出字典序最小的 $s$ 的合法排列。

**提示 2：** 一位位确定，如何找到最小的可填的数？

如果 $s$ 的初始情况确定了，我们只需依次找 $h$ 剩余元素中的第 $s[i]+1$ 小的元素不断填入即可。同时这也意味着字典序越小的 $s$ 对应着字典序越小的 $h$ 。

所以我们要找到满足条件的字典序最小的 $s$ 的排列。

我们应该一步步确定每一位填的数最小可以是什么——也就是保证去掉这个数后，剩下的元素仍然能排成合法的序列。

根据 Hall 定理，长度为 $x$ 的序列合法，当且仅当：

$cnt[x]\leq 0$

$cnt[x-1]+cnt[x]\leq 1$

$cnt[x-2]+cnt[x-1]+cnt[x]\leq 2$

$\dots$

$cnt[0]+cnt[1]+\dots+cnt[x-2]+cnt[x-1]+cnt[x]\leq x$

所以我们要更新一个结构，让它能快速判断上面的事情。

于是用左侧的每一项 $cnt[i]$ 都减去 $1$ ，这样就都是小于等于 $0$ ，也就相当于所有后缀和不超过 $0$ 。可以考虑用线段树维护上述变量。

而填的数越小越容易使得上述条件不成立，所以可以线段树上二分找到第一个操作合法的位置。然后选了这个数之后，再更新上面的各个条件即可。需要执行区间加减，所以可以使用懒更新线段树。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    hs = LII()
    vs = LII()

    hs.sort()

    cnt = [0] * n
    for x in vs:
        cnt[x] += 1

    for i in range(n - 2, -1, -1):
        cnt[i] += cnt[i + 1]

    for i in range(n):
        cnt[i] -= n - i

    if max(cnt) > 0: print(-1)
    else:
        seg = LazySegTree(fmax, 0, add, add, 0, cnt)
        fen = FenwickTree([1] * n)

        ans = [0] * n

        for i in range(n):
            seg.apply(0, n - i, 1)
            p = fmax(seg.min_left(n - i, lambda x: x <= 0) - 1, 0)
            seg.apply(0, p + 1, -1)

            target_idx = fen.bisect_min_larger(p + 1)
            fen.add(target_idx, -1)
            ans[i] = hs[target_idx]

        print(' '.join(map(str, ans)))
```

C++ 做法如下——

```cpp []
int op(int x, int y) {return max(x, y);}

int e() {return 0;}

int add(int x, int y) {return x + y;}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<int> hs(n), vs(n);
	for (auto &x: hs) cin >> x;
	for (auto &x: vs) cin >> x;

	sort(hs.begin(), hs.end());

	vector<int> cnt(n, 0);
	for (auto &x: vs) cnt[x] ++;

	for (int i = n - 2; i >= 0; i --) cnt[i] += cnt[i + 1];
	for (int i = 0; i < n; i ++) cnt[i] -= n - i;

	if (*max_element(cnt.begin(), cnt.end()) > 0) cout << -1;
	else {
		atcoder::lazy_segtree<int, op, e, int, add, add, e> seg(cnt);
		atcoder::fenwick_tree<int> fen(n);
		for (int i = 0; i < n; i ++) fen.add(i, 1);

		for (int i = 0; i < n; i ++) {
			seg.apply(0, n - i, 1);
			int p = max(seg.min_left(n - i, [&] (int x) {return x <= 0;}) - 1, 0);
			seg.apply(0, p + 1, -1);

			int target_idx = fen.lower_bound(p + 1) - 1;
			fen.add(target_idx, -1);
			cout << hs[target_idx] << " \n"[i == n - 1];
		}
	}

	return 0;
}
