**提示 1：** 求下面积就行。

最后面积长啥样呢？

实际上就是原图形往外拓出去一个半径 $r$ 。

此时，原图形的面积 $Area$ 肯定仍然在。

而除了圆角的部分，剩余部分刚好是周长 $Perimeter$ 乘以 $r$ ，因为是一些矩形。

而那些圆角，它们的分别的角度等于外角，所以整体可以拼成一个圆，所以这部分是 $\pi r^2$ 。

综上，总面积是 $\pi r^2+Perimeter r+Area$ ，我们要求它大于等于 $k$ 。

此时如果原本面积就够大了，输出 $0$ 即可。

否则，就是求解一个二次方程了。

如果你想有更高的精度，可以用分子有理化，即 $\frac{-2c}{b+\sqrt{b^2-4ac}}$ ，因为减法损失精度。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n, k = MII()
        xs = []
        ys = []

        for _ in range(n):
            x, y = MII()
            xs.append(x)
            ys.append(y)

        area = 0

        for i in range(n - 2):
            x1, y1 = xs[i + 1] - xs[0], ys[i + 1] - ys[0]
            x2, y2 = xs[i + 2] - xs[0], ys[i + 2] - ys[0]

            area += x1 * y2 - x2 * y1

        area = abs(area)

        perimeter = 0

        for i in range(n):
            dx, dy = xs[(i + 1) % n] - xs[i], ys[(i + 1) % n] - ys[i]
            perimeter += math.hypot(dx, dy)

        if area >= k * 2: outs.append('0')
        else:
            a = math.pi
            b = perimeter
            c = area / 2 - k

            outs.append(f'{-2 * c / (b + math.sqrt(b * b - 4 * a * c)):.10f}')

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	cout << fixed << setprecision(10);

	while (t --) {
		int n;
		long long k;
		cin >> n >> k;

		vector<pair<int, int>> pts(n);
		for (auto &[x, y]: pts) cin >> x >> y;

		long long area = 0;

		for (int i = 0; i < n - 2; i ++) {
			auto [x1, y1] = pts[0];
			auto [x2, y2] = pts[(i + 1) % n];
			auto [x3, y3] = pts[(i + 2) % n];

			int dx1 = x2 - x1, dy1 = y2 - y1;
			int dx2 = x3 - x1, dy2 = y3 - y1;

			area += abs(1ll * dx1 * dy2 - 1ll * dx2 * dy1);
		}

		long double perimeter = 0;

		for (int i = 0; i < n; i ++) {
			auto [x1, y1] = pts[i];
			auto [x2, y2] = pts[(i + 1) % n];
			perimeter += hypot(x1 - x2, y1 - y2);
		}

		if (area >= 2 * k) cout << 0 << '\n';
		else {
			long double a = acosl(-1), b = perimeter, c = (long double)(area - 2 * k) / 2;
			cout << -2 * c / (b + sqrtl(b * b - 4 * a * c)) << '\n';
		}
	}

	return 0;
}
```

**提示 1：** 考虑 DP 状态。

我们求两个人之间的硬币差，将其作为状态。

设到第 $i$ 个位置时，当前数值为 $x$ 的情况下，中间状态达到过的绝对值的最大值最小为 $dp[i][x]$ 。

则枚举新的一个数分给哪个人，状态会变成 $x-v$ 或 $x+v$ ，于是可以更新 $dp[i][x-v]$ 为 $\max(dp[i][x], |x-v|)$ ，更新 $dp[i][x+v]$ 为 $\max(dp[i][x],|x+v|)$ 。

因为总可以找到办法使得答案不超过 $\max a_i$ ，所以第二个状态的数据范围定为 $[-100,100]$ 即可。当然你也可以把正负合并。

时间复杂度为 $\mathcal{O}(nM)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n = II()
        nums = LII()

        dp = [inf] * 201
        dp[100] = 0

        for x in nums:
            ndp = [inf] * 201

            for i in range(201):
                if i - x >= 0:
                    ndp[i] = fmin(ndp[i], dp[i - x])
                if i + x <= 200:
                    ndp[i] = fmin(ndp[i], dp[i + x])
                ndp[i] = fmax(ndp[i], abs(i - 100))

            dp = ndp

        outs.append(min(dp))

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<int> dp(201, (int)1e9);
		dp[100] = 0;

		while (n --) {
			int x;
			cin >> x;

			vector<int> ndp(201, (int)1e9);

			for (int i = 0; i <= 200; i ++) {
				if (i - x >= 0) ndp[i] = min(ndp[i], dp[i - x]);
				if (i + x <= 200) ndp[i] = min(ndp[i], dp[i + x]);
				ndp[i] = max(ndp[i], abs(i - 100));
			}

			dp.swap(ndp);
		}

		cout << *min_element(dp.begin(), dp.end()) << '\n';
	}

	return 0;
}
```

**提示 1：** 考虑 DP 状态。

考虑到第 $i$ 天为止，最后一个使用的活动是第 $j$ 个的情况下的最优分数 $dp[i][j]$ 。

则我们可以继续做这个活动，我们认为此时已经到了 $c\gt d_i$ 的时期，因此将 $dp[i][j]+k_j-x_j$ 转移到 $dp[i+1][j]$ ，这样可以统一处理后面 $k-x$ 的部分，比较方便

接下来我们考虑 $c\leq d_i$ 的部分。此时假设转移到 $dp[i+c][j]$ ，则 $c$ 应当枚举 $1\sim d_i$ 的任意值。同时转移前使用的活动必须不等于 $j'$ ，所以我们需要找到 $\max_{j'\neq j} dp[i][j']$ ，加上 $ck_i$ 得到转移，为此，只需维护 $i$ 那一层的最大值和次大值即可。

时间复杂度为 $\mathcal{O}(nz\max(d))$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, z = MII()

    ks = [0]
    ds = [1]
    xs = [0]

    for _ in range(n):
        k, d, x = MII()
        ks.append(k)
        ds.append(d)
        xs.append(x)

    dp = [[0] * (n + 1) for _ in range(z + 1)]

    for i in range(z):
        ma1 = 0
        ma2 = 0

        for j in range(n + 1):
            dp[i + 1][j] = fmax(dp[i + 1][j], dp[i][j] + ks[j] - xs[j])

            if dp[i][j] > ma1: ma1, ma2 = dp[i][j], ma1
            elif dp[i][j] > ma2: ma2 = dp[i][j]

        for j in range(n + 1):
            nd = fmin(z - i, ds[j])

            for x in range(1, nd + 1):
                dp[i + x][j] = fmax(dp[i + x][j], (ma2 if dp[i][j] == ma1 else ma1) + x * ks[j])

    print(max(dp[z]))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, z;
	cin >> n >> z;

	vector<array<int, 3>> activities(n);
	for (auto &[k, d, x]: activities) cin >> k >> d >> x;

	activities.push_back({0, 1, 0});

	vector<vector<long long>> dp(z + 1, vector<long long>(n + 1, 0));

	for (int i = 0; i < z; i ++) {
		long long ma1 = 0, ma2 = 0;

		for (int j = 0; j <= n; j ++) {
			auto [k, d, x] = activities[j];
			dp[i + 1][j] = max(dp[i + 1][j], dp[i][j] + k - x);

			if (dp[i][j] > ma1) swap(ma1, ma2), ma1 = dp[i][j];
			else if (dp[i][j] > ma2) ma2 = dp[i][j];
		}

		for (int j = 0; j <= n; j ++) {
			auto [k, d, x] = activities[j];
			int nd = min(z - i, d);

			for (int v = 1; v <= nd; v ++)
				dp[i + v][j] = max(dp[i + v][j], (dp[i][j] == ma1 ? ma2 : ma1) + 1ll * v * k);
		}
	}

	cout << *max_element(dp[z].begin(), dp[z].end());

	return 0;
}
```

**提示 1：** 哪些人会必胜？

我们用总组数 $\binom{n}{k}$ 减去不合法的组数即可。

什么情况下会有个人必胜呢？就是这个人的两个参数比其余的任何人都高。

所以我们枚举这个人，统计两项都严格劣于这个人的人数 $c$ ，减去分别的 $\binom{c}{k}$ 即可。

时间复杂度为 $\mathcal{O}(n^2)$ ，如果用二维数点可以进一步优化到 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, k = MII()
    p = LII()
    s = LII()

    mod = 998244353
    f = Factorial(n, mod)

    ans = f.combi(n, k)

    for i in range(n):
        c = 0
        for j in range(n):
            if p[j] < p[i] and s[j] < s[i]:
                c += 1

        ans -= f.combi(c, k - 1)
        ans %= mod

    print(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, k, mod = 998244353;
	cin >> n >> k;

	vector<int> p(n), s(n);
	for (auto &x: p) cin >> x;
	for (auto &x: s) cin >> x;

	vector<int> f(n + 1), g(n + 1);
	f[0] = 1;
	for (int i = 1; i <= n; i ++) f[i] = 1ll * f[i - 1] * i % mod;
	g[n] = quickPow(f[n], mod - 2, mod);
	for (int i = n; i >= 1; i --) g[i - 1] = 1ll * g[i] * i % mod;

	auto comb = [&] (int x, int y) -> int {
		if (y < 0 || y > x) return 0;
		return 1ll * f[x] * g[y] % mod * g[x - y] % mod;
	};

	int ans = comb(n, k);

	for (int i = 0; i < n; i ++) {
		int c = 0;
		for (int j = 0; j < n; j ++) {
			if (p[j] < p[i] && s[j] < s[i]) {
				c ++;
			}
		}
		ans += mod - comb(c, k - 1);
		ans %= mod;
	}

	cout << ans;

	return 0;
}
```

**提示 1：** 想想 $\lceil\log_2n!\rceil-1$ 是怎么来的。

每一步比较相当于一个分类器，把全集分为两个部分，只留下其中的一个部分。

而在 $\lceil\log_2n!\rceil-1$ 次操作下，每次保留较大的那个部分，最后剩下的排列数量一定不小于 $2$ ，也就是没有完成排序。

而如何留方案数较多的部分呢？可以假定其中的一种情况，用 bitmask DP 算出这种情况的方案数，再用总方案数减去它就可以得到另一种情况的方案数。

最后如何得到另一个排列呢？相当于要找最终序列的另一个拓扑序。于是在拓扑排序的过程中，一旦可以选择不等于给定拓扑序的对应位置元素，我们就选它，这样就能完成任务了。

时间复杂度为 $\mathcal{O}(n 2^n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    path = [0] * n

    dp = [0] * (1 << n)
    dp[0] = 1

    def count_method():
        for i in range(1, 1 << n):
            dp[i] = 0
            cur = i

            while cur:
                v = cur & -cur
                bit = v.bit_length() - 1
                if path[bit] & i == 0:
                    dp[i] += dp[i - v]
                cur -= v

        return dp[-1]

    total = math.factorial(n)

    while True:
        query = LI()

        if query[0] == '?':
            x = int(query[1]) - 1
            y = int(query[2]) - 1

            orig = path[x]
            path[x] |= 1 << y
            w1 = count_method()
            path[x] = orig

            w2 = total - w1

            if w1 >= w2:
                path[x] |= 1 << y
                total = w1
                print('<', flush=True)
            else:
                path[y] |= 1 << x
                total = w2
                print('>', flush=True)

        else:
            p = [int(x) - 1 for x in query[1:]]
            indeg = [0] * n

            for i in range(n):
                for j in range(n):
                    if path[i] >> j & 1:
                        indeg[j] += 1

            cur = []
            stk = [i for i in range(n) if indeg[i] == 0]

            for _ in range(n):
                if len(stk) > 1 and stk[-1] == p[len(cur)]:
                    stk.reverse()

                u = stk.pop()
                cur.append(u)

                for v in range(n):
                    if path[u] >> v & 1:
                        indeg[v] -= 1
                        if indeg[v] == 0:
                            stk.append(v)

            print('!', *(x + 1 for x in cur), flush=True)

            break
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	long long total_method = 1;
	for (int i = 1; i <= n; i ++) total_method *= i;

	vector<int> path(n, 0);
	vector<long long> dp(1 << n, 0);
	dp[0] = 1;

	auto count_method = [&] () -> long long {
		for (int i = 1; i < (1 << n); i ++) {
			dp[i] = 0;
			int cur = i;

			while (cur) {
				int bit = __builtin_ctz(cur);
				if ((path[bit] & i) == 0) dp[i] += dp[i - (1 << bit)];
				cur -= cur & -cur;
			}
		}
		return dp.back();
	};

	while (true) {
		char c;
		cin >> c;

		if (c == '?') {
			int x, y;
			cin >> x >> y;
			x --, y --;

			int orig = path[x];
			path[x] |= 1 << y;
			long long w1 = count_method();
			path[x] = orig;

			long long w2 = total_method - w1;

			if (w1 >= w2) {
				path[x] |= 1 << y;
				total_method = w1;
				cout << '<' << endl;
			}
			else {
				path[y] |= 1 << x;
				total_method = w2;
				cout << '>' << endl;
			}
		}
		else {
			vector<int> p(n);
			for (auto &x: p) cin >> x, x --;

			vector<int> indeg(n);

			for (int i = 0; i < n; i ++) {
				for (int j = 0; j < n; j ++) {
					if (path[i] >> j & 1) {
						indeg[j] ++;
					}
				}
			}

			vector<int> cur, stk;

			for (int i = 0; i < n; i ++) {
				if (indeg[i] == 0) {
					stk.emplace_back(i);
				}
			}

			for (int i = 0; i < n; i ++) {
				if (stk.size() > 1 && stk.back() == p[cur.size()])
					reverse(stk.begin(), stk.end());

				int u = stk.back();
				stk.pop_back();
				cur.emplace_back(u);

				for (int v = 0; v < n; v ++) {
					if (path[u] >> v & 1) {
						indeg[v] --;
						if (indeg[v] == 0) stk.emplace_back(v);
					}
				}
			}

			cout << '!';
			for (auto &x: cur) cout << ' ' << x + 1;
			cout << endl;

			break;
		}
	}

	return 0;
}
```

**提示 1：** 假设我们知道了目标数值，最少操作几次呢？

假设我们已经知道了目标数组的最终数值，此时，每一段不等于目标数值的段落，设长度为 $len$ ，至少需要 $len$ 次平移操作，才能让这一段的每个位置都被目标数组的最终数值遍历过一次（因为一次平移只能多覆盖这一段的一个位置）。

所以最小的平移次数等于最长的不等于目标数值的段落长度（考虑成环形数组）。

而这也是可以取到的，只往一个方向移动就行。然后一旦遇到可以赋值的位置赋值即可——因为还有赋值操作，对结果加上 $n$ 即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    nums = LII()

    M = 10 ** 5 + 5

    first_pos = [-1] * M
    last_pos = [-1] * M

    res = [0] * M

    for i in range(n):
        if first_pos[nums[i]] == -1:
            first_pos[nums[i]] = i
        else:
            res[nums[i]] = fmax(res[nums[i]], i - last_pos[nums[i]] - 1)
        last_pos[nums[i]] = i

    ans = n

    for i in range(M):
        if first_pos[i] != -1:
            res[i] = fmax(res[i], first_pos[i] + n - 1 - last_pos[i])
            ans = fmin(ans, res[i])

    print(ans + n)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, M = 1e5 + 5;
	cin >> n;

	vector<int> first_pos(M, -1), last_pos(M, -1), res(M);

	for (int i = 0; i < n; i ++) {
		int x;
		cin >> x;

		if (first_pos[x] == -1) first_pos[x] = i;
		else res[x] = max(res[x], i - last_pos[x] - 1);

		last_pos[x] = i;
	}

	int ans = n;

	for (int i = 0; i < M; i ++) {
		if (first_pos[i] != -1) {
			res[i] = max(res[i], first_pos[i] + n - 1 - last_pos[i]);
			ans = min(ans, res[i]);
		}
	}

	cout << ans + n;

	return 0;
}
