**提示 1：** 如果知道区间里各个元素的频率，就可以快速求答案了。如何计算区间内的频率信息呢？

如果我们知道了区间内各个元素的频率，接下来怎么做呢？

枚举第一个数组选的元素是 $1,2,\dots,\lfloor\sqrt{k}\rfloor$ 中的哪一个，设选的是 $i$ ，则我们要统计第二个数组中不超过 $\lfloor k/ i \rfloor$ 的元素个数。

同样接下来枚举第二个数组选的元素是哪一个，进行一样的流程。

最后，这样多算了两个元素都不超过 $\lfloor\sqrt{k}\rfloor$ 的情况，去掉它们即可。

那如何得到区间内各个元素的出现频率呢？直接莫队，新增元素和删去元素的时候在树状数组里操作即可。这样空间也控制在线性了。

时间复杂度为 $\mathcal{O}(q\log q+n\sqrt{q}\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, q = MII()
    v1 = LII()
    v2 = LII()

    ls = []
    rs = []
    ks = []

    for _ in range(q):
        l, r, k = MII()
        ls.append(l - 1)
        rs.append(r)
        ks.append(k)

    ans = [0] * q

    B = 320

    st_range = sorted(range(q), key=lambda x: (ls[x] // B, rs[x] if ls[x] // B % 2 else -rs[x]))

    M = 10 ** 5 + 1
    cnt1 = [0] * M
    fen1 = FenwickTree(M)
    cnt2 = [0] * M
    fen2 = FenwickTree(M)

    pl = 0
    pr = 0

    for i in st_range:
        l = ls[i]
        r = rs[i]
        k = ks[i]

        while pl > l:
            pl -= 1

            if v1[pl] < M:
                cnt1[v1[pl]] += 1
                fen1.add(v1[pl], 1)

            if v2[pl] < M:
                cnt2[v2[pl]] += 1
                fen2.add(v2[pl], 1)

        while pr < r:
            if v1[pr] < M:
                cnt1[v1[pr]] += 1
                fen1.add(v1[pr], 1)

            if v2[pr] < M:
                cnt2[v2[pr]] += 1
                fen2.add(v2[pr], 1)

            pr += 1

        while pl < l:
            if v1[pl] < M:
                cnt1[v1[pl]] -= 1
                fen1.add(v1[pl], -1)

            if v2[pl] < M:
                cnt2[v2[pl]] -= 1
                fen2.add(v2[pl], -1)

            pl += 1

        while pr > r:
            pr -= 1

            if v1[pr] < M:
                cnt1[v1[pr]] -= 1
                fen1.add(v1[pr], -1)

            if v2[pr] < M:
                cnt2[v2[pr]] -= 1
                fen2.add(v2[pr], -1)

        bound = math.isqrt(k)
        w1 = 0
        w2 = 0

        for cur in range(1, bound + 1):
            ans[i] += cnt1[cur] * fen2.rsum(0, k // cur)
            w1 += cnt1[cur]

            ans[i] += cnt2[cur] * fen1.rsum(0, k // cur)
            w2 += cnt2[cur]

        ans[i] -= w1 * w2

    print('\n'.join(map(str, ans)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, q;
	cin >> n >> q;

	vector<int> v1(n), v2(n);
	for (auto &x: v1) cin >> x;
	for (auto &x: v2) cin >> x;

	vector<array<int, 3>> queries(q);
	for (auto &[l, r, k]: queries) cin >> l >> r >> k, l --;

	int B = 320;

	vector<int> order(q);

	iota(order.begin(), order.end(), 0);
	sort(order.begin(), order.end(), [&] (int i, int j) {
		int l1 = queries[i][0] / B, r1 = queries[i][1];
		int l2 = queries[j][0] / B, r2 = queries[j][1];

		if (l1 != l2) return l1 < l2;
		if (l1 % 2) return r1 < r2;
		else return r1 > r2;
	});

	int M = 1e5 + 1;
	vector<int> cnt1(M, 0), cnt2(M, 0);
	atcoder::fenwick_tree<int> fen1(M), fen2(M);

	vector<long long> outs(q);

	int pl = 0, pr = 0;

	for (auto &qidx: order) {
		auto [l, r, k] = queries[qidx];

		while (pl > l) {
			pl --;
			if (v1[pl] < M) {
				cnt1[v1[pl]] ++;
				fen1.add(v1[pl], 1);
			}
			if (v2[pl] < M) {
				cnt2[v2[pl]] ++;
				fen2.add(v2[pl], 1);
			}
		}

		while (pr < r) {
			if (v1[pr] < M) {
				cnt1[v1[pr]] ++;
				fen1.add(v1[pr], 1);
			}
			if (v2[pr] < M) {
				cnt2[v2[pr]] ++;
				fen2.add(v2[pr], 1);
			}
			pr ++;
		}

		while (pl < l) {
			if (v1[pl] < M) {
				cnt1[v1[pl]] --;
				fen1.add(v1[pl], -1);
			}
			if (v2[pl] < M) {
				cnt2[v2[pl]] --;
				fen2.add(v2[pl], -1);
			}
			pl ++;
		}

		while (pr > r) {
			pr --;
			if (v1[pr] < M) {
				cnt1[v1[pr]] --;
				fen1.add(v1[pr], -1);
			}
			if (v2[pr] < M) {
				cnt2[v2[pr]] --;
				fen2.add(v2[pr], -1);
			}
		}

		long long ans = 0;
		int w1 = 0, w2 = 0;

		for (int i = 1; i * i <= k; i ++) {
			ans += 1ll * cnt1[i] * fen2.sum(0, k / i + 1);
			ans += 1ll * cnt2[i] * fen1.sum(0, k / i + 1);
			w1 += cnt1[i], w2 += cnt2[i];
		}

		ans -= 1ll * w1 * w2;
		outs[qidx] = ans;
	}

	for (auto &v: outs) cout << v << '\n';

	return 0;
}
```

**提示 1：** 如何统计 $X$ 以下有多少个满足条件的数。

直接算第 $x$ 个数是不方便的。所以考虑二分，如果我们能统计 $X$ 以下有多少个符合条件的数，我们只需找到这样的 $X$ 的最小值即可。

而这件事儿可以用容斥来做。先分别减去 $2^2,3^2,5^2,\dots$ 等质数的平方的倍数。

但至少有两个质数平方的因子的数会被多算，于是减掉 $(p_1p_2)^2$ 形式的数的倍数。

但三个质因子的又被多加了，于是应该减去。

类似地，得到多个质因子的情况，因子个数为奇数的情况下系数为负，否则为正。

而开根号后的范围在 $\sqrt{M}$ 量级，因此我们统计这个范围内每个元素的质因子个数——注意上面开根号后因子个数都是 $1$ ，所以一旦有一个因子有超过 $1$ 次，则这个数对应的系数为 $0$ 。

整体系数类似莫比乌斯反演那一套。

最后根据上述逻辑统计即可。如果有不清楚的细节可以看后面的代码。

时间复杂度为 $\mathcal{O}(\sqrt{M}\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    M = 200000

    is_prime = [1] * M
    is_prime[0] = 0
    is_prime[1] = 0

    miu = [1] * M

    for i in range(M):
        if is_prime[i]:
            for j in range(i, M, i):
                is_prime[j] = 0
                miu[j] *= -1

                if j // i % i == 0:
                    miu[j] = 0

    chosen = [i for i in range(1, M) if miu[i]]

    t = II()
    outs = []

    for _ in range(t):
        x = II()

        l, r = 1, 4 * 10 ** 10
        while l <= r:
            mid = (l + r) // 2

            cnt = 0

            for i in chosen:
                cnt += miu[i] * (mid // i // i)

            if cnt >= x: r = mid - 1
            else: l = mid + 1

        outs.append(l)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int M = 2e5;

	vector<int> is_prime(M, 1);
	is_prime[0] = 0, is_prime[1] = 0;

	vector<int> miu(M, 1);

	for (int i = 1; i <= M; i ++) {
		if (is_prime[i]) {
			for (int j = i; j <= M; j += i) {
				is_prime[j] = 0;
				miu[j] *= -1;
				if (j / i % i == 0) miu[j] = 0;
			}
		}
	}

	vector<int> chosen;
	for (int i = 1; i < M; i ++) if (miu[i]) chosen.emplace_back(i);

	int t;
	cin >> t;

	while (t --) {
		long long target;
		cin >> target;

		long long l = 1, r = 4e10;

		while (l <= r) {
			long long mid = (l + r) / 2, cnt = 0;
			for (auto &x: chosen) {
				cnt += miu[x] * (mid / x / x);
			}
			if (cnt >= target) r = mid - 1;
			else l = mid + 1;
 		}

		cout << l << '\n';
	}

	return 0;
}
```

**提示 1：** 找到合适的起点。

图上每个点都等价，因此任意选取一点并不能帮助我们找到搜索的方向。

如果选取一条边呢？

发现选取棱上的一条边，则上侧跟上端点的距离更近，其余点在下侧——我们就可以把点分为上下两部分了，这是很方便的。

所以假定我们找到了一条棱。也就找到了上下的两个环——我们先确认下上下两个是否分别是环。

而剩余的边需要将上面的环上的点和底下的环上的点进行一一对应。只需判断上面的相邻的两点连到的底下的两个点之间是不是也恰好有一条边。

那怎么找到棱呢？其实不用找。一个点总共连出来三条边，分别尝试即可。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    path = [[] for _ in range(n)]

    for _ in range(n // 2 * 3):
        u, v = GMI()
        path[u].append(v)
        path[v].append(u)

    if any(len(path[i]) != 3 for i in range(n)): print('NO')
    else:
        def check(x, y):
            que = [x, y]

            dis = [-1] * n
            dis[x] = 0
            dis[y] = 0

            npath = [[] for _ in range(n)]

            for u in que:
                for v in path[u]:
                    if dis[v] == -1:
                        dis[v] = dis[u] + 1
                        npath[u].append(v)
                        npath[v].append(u)
                        que.append(v)

            for i in range(n):
                if len(npath[i]) > 2: return

            vis = [0] * n
            chains = []

            for i in range(n):
                if not vis[i] and len(npath[i]) == 1:
                    chain = [i]
                    vis[i] = 1

                    for u in chain:
                        for v in npath[u]:
                            if not vis[v]:
                                vis[v] = 1
                                chain.append(v)

                    chains.append(chain)

            if len(chains) != 2 or len(chains[0]) != n // 2 or len(chains[1]) != n // 2: return
            if chains[0][0] not in path[chains[0][-1]]: return
            if chains[1][0] not in path[chains[1][-1]]: return

            idxs = [-1] * n
            for i in range(n // 2):
                idxs[chains[0][i]] = i

            tmp = []
            for i in range(n // 2):
                u = chains[1][i]
                chosen = -1

                for v in path[u]:
                    if idxs[v] != -1:
                        chosen = idxs[v]

                if chosen == -1: return
                tmp.append(chosen)

            diff = (tmp[1] - tmp[0]) % (n // 2)

            if diff != 1 and diff != n // 2 - 1: return

            for i in range(1, n // 2):
                if (tmp[i] - tmp[i - 1]) % (n // 2) != diff:
                    return

            print('YES')
            print(' '.join(str(x + 1) for x in chains[1]))
            print(' '.join(str(chains[0][x] + 1) for x in tmp))
            exit()

        for v in path[0]:
            check(0, v)

        print('NO')
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<vector<int>> path(n);

	for (int i = 0; i < n / 2 * 3; i ++) {
		int u, v;
		cin >> u >> v;
		u --, v --;
		path[u].emplace_back(v);
		path[v].emplace_back(u);
	}

	bool flg;

	flg = true;

	for (auto &v: path) if (v.size() != 3) flg = false;

	if (!flg) cout << "NO\n";
	else {
		auto check = [&] (int x, int y) -> void {
			vector<int> que = {x, y};

			vector<int> dis(n, -1);
			dis[x] = 0, dis[y] = 0;

			vector<vector<int>> npath(n);

			for (int i = 0; i < que.size(); i ++) {
				int u = que[i];
				for (auto &v: path[u]) {
					if (dis[v] == -1) {
						dis[v] = dis[u] + 1;
						npath[u].emplace_back(v);
						npath[v].emplace_back(u);
						que.emplace_back(v);
					}
				}
			}

			for (int i = 0; i < n; i ++) {
				if (npath[i].size() > 2) {
					return ;
				}
			}

			vector<int> vis(n, 0);
			vector<vector<int>> chains;

			for (int i = 0; i < n; i ++) {
				if (!vis[i] && npath[i].size() == 1) {
					vector<int> chain = {i};
					vis[i] = 1;

					for (int j = 0; j < chain.size(); j ++) {
						int u = chain[j];
						for (auto &v: npath[u]) {
							if (!vis[v]) {
								vis[v] = 1;
								chain.emplace_back(v);
							}
						}
					}

					chains.emplace_back(chain);
				}
			}

			if (chains.size() != 2 || chains[0].size() != n / 2 || chains[1].size() != n / 2) return ;

			flg = false;
			for (auto &x: path[chains[0][0]]) if (chains[0].back() == x) flg = true;
			if (!flg) return ;

			flg = false;
			for (auto &x: path[chains[1][0]]) if (chains[1].back() == x) flg = true;
			if (!flg) return ;

			vector<int> idxs(n, -1);
			for (int i = 0; i < n / 2; i ++) idxs[chains[0][i]] = i;

			vector<int> tmp;
			for (int i = 0; i < n / 2; i ++) {
				int u = chains[1][i], chosen = -1;

				for (auto &v: path[u]) {
					if (idxs[v] != -1) {
						chosen = idxs[v];
					}
				}

				if (chosen == -1) return ;
				tmp.emplace_back(chosen);
			}

			int diff = (tmp[1] - tmp[0] + n) % (n / 2);

			if (diff != 1 && diff != n / 2 - 1) return ;

			for (int i = 1; i < n / 2; i ++) {
				if ((tmp[i] - tmp[i - 1] + n) % (n / 2) != diff) {
					return ;
				}
			}

			cout << "YES\n";
			for (auto &x: chains[1]) cout << x + 1 << ' '; cout << '\n';
			for (auto &x: tmp) cout << chains[0][x] + 1 << ' '; cout << '\n';
			exit(0);
		};

		for (auto &v: path[0]) check(0, v);

		cout << "NO\n";
	}

	return 0;
}
