**提示 2：** 遍历每条边两次……

直接找遍历所有点的好路径的算法是很难办的。

但从贪心的意义来看，只需取小边权就行。而 $2$ 的常数就允许我们走两遍。

所以直接取整个图的最小生成树，再 DFS 序遍历每一条边即可。

时间复杂度为 $\mathcal{O}(m\log m+n)$ ，复杂度主要取决于你使用的最小生成树算法。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()

    us = []
    vs = []
    ws = []

    for _ in range(m):
        u, v, w = MII()
        us.append(u - 1)
        vs.append(v - 1)
        ws.append(w)

    uf = UnionFind(n)

    ans = 0
    path = [[] for _ in range(n)]

    for i in sorted(range(m), key=lambda x: ws[x]):
        u, v = us[i], vs[i]
        if uf.merge(u, v):
            ans += ws[i]
            path[u].append(v)
            path[v].append(u)

    parent = [-1] * n

    stk = [0]
    order = []

    while stk:
        u = stk.pop()

        if u >= 0:
            order.append(u)
            stk.append(~u)

            for v in path[u]:
                if parent[u] != v:
                    parent[v] = u
                    stk.append(v)

    res = [0]
    stk = [0]

    for u in order:
        if u:
            while res[-1] != parent[u]:
                stk.pop()
                res.append(stk[-1])
            stk.append(u)
            res.append(stk[-1])

    while stk[-1] != 0:
        stk.pop()
        res.append(stk[-1])

    print(ans * 2)
    print(len(res))
    print(' '.join(str(x + 1) for x in res))
```

C++ 做法如下——

```cpp []
typedef pair<pair<int, int>, long long> edge;

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> n >> m;

	vector<edge> edges(m);
	for (auto &[x, y]: edges) cin >> x.first >> x.second >> y;

	sort(edges.begin(), edges.end(), [&] (edge e1, edge e2) {return e1.second < e2.second;});

	atcoder::dsu uf(n + 1);
	vector<vector<int>> path(n + 1);

	long long ans = 0;

	for (auto &[ends, w]: edges) {
		auto [u, v] = ends;
		if (uf.merge(u, v)) {
			ans += w;
			path[u].emplace_back(v);
			path[v].emplace_back(u);
		}
	}

	cout << 2 * ans << '\n';

	vector<int> order;

	auto dfs = [&] (auto &self, int u, int p) -> void {
		order.emplace_back(u);
		for (auto &v: path[u]) {
			if (v != p) {
				self(self, v, u);
				order.emplace_back(u);
			}
		}
	};

	dfs(dfs, 1, 0);

	cout << 2 * n - 1 << '\n';
	for (int i = 0; i < 2 * n - 1; i ++) cout << order[i] << " \n"[i == 2 * n - 2];

	return 0;
}
