	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	string s, t;
	int p, q;
	cin >> s >> t >> p >> q;

	if (!p || !q) cout << '=';
	else {
		string s1 = s + t;
		string s2 = t + s;

		if (s1 < s2) cout << '<';
		else if (s1 > s2) cout << '>';
		else cout << '=';
	}

	return 0;
}
