**提示 1：** 其实很多区域内的元素都是一回事。

给定的长方形建筑物的数量并不多。

所以可以考虑直接用这些边界对应的直线，把整个 $n\times n$ 的区域分为 $\mathcal{O}(k^2)$ 块，则块内的最短路应该可以只通过角上的四个点确认，即从起点触发到达一个角，再走到当前结点。

当然这里需要注意下，可能存在路径使得起点可以用曼哈顿距离走到终点，在上面的讨论下不成立。但是我们可以强行加入 $x=u,y=v$ 两条直线分割线，这样就有新增的角点可以解决这种边界情况了。

接下来，我们用差分维护下 $\mathcal{O}(k^2)$ 个障碍物的对应的块，就可以标记出哪些位置是不能走的了。

接下来，在这个网格图中跑最短路即可得到每个角点的数值。查询时，先找到对应的块和块的角点（注意你找到的块里不能包含障碍物，不然会出错），接下来枚举这个块的四个角点，用四个角点的最短路加上角点到查询点的曼哈顿距离即答案。

思维上其实并不难，但是写起来太丑了，导致给了个不低的分。

时间复杂度为 $\mathcal{O}((k^2+q)\log k)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    outs = []

    while True:
        n, u, v = MII()

        if n == 0 and u == 0 and v == 0: break

        m = II()

        xs = [1, u, n]
        ys = [1, v, n]

        recs = []

        for _ in range(m):
            x1, x2, y1, y2 = MII()

            if x1 - 1 >= 1: xs.append(x1 - 1)
            xs.append(x1)
            xs.append(x2)
            if x2 + 1 <= n: xs.append(x2 + 1)

            if y1 - 1 >= 1: ys.append(y1 - 1)
            ys.append(y1)
            ys.append(y2)
            if y2 + 1 <= n: ys.append(y2 + 1)

            recs.append((x1, x2, y1, y2))

        xs = sorted(set(xs))
        ys = sorted(set(ys))

        N = len(xs)
        M = len(ys)

        grid = [[0] * M for _ in range(N)]

        for x1, x2, y1, y2 in recs:
            px1 = bisect.bisect_left(xs, x1)
            px2 = bisect.bisect_left(xs, x2 + 1)

            py1 = bisect.bisect_left(ys, y1)
            py2 = bisect.bisect_left(ys, y2 + 1)

            grid[px1][py1] += 1
            if px2 < N: grid[px2][py1] -= 1
            if py2 < M: grid[px1][py2] -= 1
            if px2 < N and py2 < M: grid[px2][py2] += 1

        for i in range(N):
            for j in range(1, M):
                grid[i][j] += grid[i][j - 1]

        for i in range(1, N):
            for j in range(M):
                grid[i][j] += grid[i - 1][j]

        dis = [[inf] * M for _ in range(N)]

        def f(x, y): return x * M + y

        def g(dis, x, y): return dis * N * M + f(x, y)

        sx = bisect.bisect_left(xs, u)
        sy = bisect.bisect_left(ys, v)

        dis[sx][sy] = 0

        pq = [g(0, sx, sy)]

        while pq:
            msk = heappop(pq)
            d, msk = divmod(msk, N * M)
            x, y = divmod(msk, M)

            if dis[x][y] == d:
                if x and grid[x - 1][y] == 0:
                    nd = d + xs[x] - xs[x - 1]
                    if dis[x - 1][y] > nd:
                        dis[x - 1][y] = nd
                        heappush(pq, g(dis[x - 1][y], x - 1, y))

                if x + 1 < N and grid[x + 1][y] == 0:
                    nd = d + xs[x + 1] - xs[x]
                    if dis[x + 1][y] > nd:
                        dis[x + 1][y] = nd
                        heappush(pq, g(dis[x + 1][y], x + 1, y))

                if y and grid[x][y - 1] == 0:
                    nd = d + ys[y] - ys[y - 1]
                    if dis[x][y - 1] > nd:
                        dis[x][y - 1] = nd
                        heappush(pq, g(dis[x][y - 1], x, y - 1))

                if y + 1 < M and grid[x][y + 1] == 0:
                    nd = d + ys[y + 1] - ys[y]
                    if dis[x][y + 1] > nd:
                        dis[x][y + 1] = nd
                        heappush(pq, g(dis[x][y + 1], x, y + 1))

        q = II()

        for _ in range(q):
            x, y = MII()
            pxl = bisect.bisect_right(xs, x) - 1
            pyl = bisect.bisect_right(ys, y) - 1

            pxr = pxl + 1 if pxl + 1 < N and grid[pxl + 1][pyl] == 0 else pxl
            pyr = pyl + 1 if pyl + 1 < M and grid[pxl][pyl + 1] == 0 else pyl

            ans = inf
            for i in range(pxl, pxr + 1):
                for j in range(pyl, pyr + 1):
                    if grid[i][j] == 0:
                        ans = fmin(ans, dis[i][j] + abs(xs[i] - x) + abs(ys[j] - y))

            outs.append(str(ans) if ans < inf else 'no')

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	long long inf = 2e18;

	while (true) {
		int n, u, v;
		cin >> n >> u >> v;

		if (!n && !u && !v) break;

		int m;
		cin >> m;

		vector<int> xs = {1, u, n}, ys = {1, v, n};
		vector<array<int, 4>> recs(m);

		for (auto &[x1, x2, y1, y2]: recs) {
			cin >> x1 >> x2 >> y1 >> y2;

			if (x1 - 1 >= 1) xs.emplace_back(x1 - 1);
			xs.emplace_back(x1);
			xs.emplace_back(x2);
			if (x2 + 1 <= n) xs.emplace_back(x2 + 1);

			if (y1 - 1 >= 1) ys.emplace_back(y1 - 1);
			ys.emplace_back(y1);
			ys.emplace_back(y2);
			if (y2 + 1 <= n) ys.emplace_back(y2 + 1);
		}

		sort(xs.begin(), xs.end());
		xs.erase(unique(xs.begin(), xs.end()), xs.end());

		sort(ys.begin(), ys.end());
		ys.erase(unique(ys.begin(), ys.end()), ys.end());

		int N = xs.size(), M = ys.size();

		vector<vector<int>> grid(N, vector<int>(M, 0));

		for (auto &[x1, x2, y1, y2]: recs) {
			int px1 = lower_bound(xs.begin(), xs.end(), x1) - xs.begin();
			int px2 = lower_bound(xs.begin(), xs.end(), x2 + 1) - xs.begin();

			int py1 = lower_bound(ys.begin(), ys.end(), y1) - ys.begin();
			int py2 = lower_bound(ys.begin(), ys.end(), y2 + 1) - ys.begin();

			grid[px1][py1] ++;
			if (px2 < N) grid[px2][py1] --;
			if (py2 < M) grid[px1][py2] --;
			if (px2 < N && py2 < M) grid[px2][py2] ++;
		}

		for (int i = 0; i < N; i ++) {
			for (int j = 1; j < M; j ++) {
				grid[i][j] += grid[i][j - 1];
			}
		}

		for (int i = 1; i < N; i ++) {
			for (int j = 0; j < M; j ++) {
				grid[i][j] += grid[i - 1][j];
			}
		}

		vector<vector<long long>> dis(N, vector<long long>(M, inf));

		int sx = lower_bound(xs.begin(), xs.end(), u) - xs.begin();
		int sy = lower_bound(ys.begin(), ys.end(), v) - ys.begin();

		dis[sx][sy] = 0;

		priority_queue<array<long long, 3>, vector<array<long long, 3>>, greater<array<long long, 3>>> pq;

		pq.push({0, sx, sy});

		while (!pq.empty()) {
			auto [d, x, y] = pq.top(); pq.pop();

			if (dis[x][y] == d) {
				if (x && grid[x - 1][y] == 0) {
					long long nd = d + xs[x] - xs[x - 1];
					if (dis[x - 1][y] > nd) {
						dis[x - 1][y] = nd;
						pq.push({dis[x - 1][y], x - 1, y});
					}
				}

				if (x + 1 < N && grid[x + 1][y] == 0) {
					long long nd = d + xs[x + 1] - xs[x];
					if (dis[x + 1][y] > nd) {
						dis[x + 1][y] = nd;
						pq.push({dis[x + 1][y], x + 1, y});
					}
				}

				if (y && grid[x][y - 1] == 0) {
					long long nd = d + ys[y] - ys[y - 1];
					if (dis[x][y - 1] > nd) {
						dis[x][y - 1] = nd;
						pq.push({dis[x][y - 1], x, y - 1});
					}
				}

				if (y + 1 < M && grid[x][y + 1] == 0) {
					long long nd = d + ys[y + 1] - ys[y];
					if (dis[x][y + 1] > nd) {
						dis[x][y + 1] = nd;
						pq.push({dis[x][y + 1], x, y + 1});
					}
				}
			}
		}

		int q;
		cin >> q;

		while (q --) {
			int x, y;
			cin >> x >> y;

			int pxl = upper_bound(xs.begin(), xs.end(), x) - xs.begin() - 1;
			int pyl = upper_bound(ys.begin(), ys.end(), y) - ys.begin() - 1;

			int pxr = (pxl + 1 < N && grid[pxl + 1][pyl] == 0) ? pxl + 1 : pxl;
			int pyr = (pyl + 1 < M && grid[pxl][pyl + 1] == 0) ? pyl + 1 : pyl;

			long long ans = inf;

			for (int i = pxl; i <= pxr; i ++) {
				for (int j = pyl; j <= pyr; j ++) {
					if (grid[i][j] == 0) {
						ans = min(ans, dis[i][j] + abs(xs[i] - x) + abs(ys[j] - y));
					}
				}
			}

			if (ans < inf) cout << ans << '\n';
			else cout << "no\n";
		}
	}

	return 0;
}
