**提示 1：** 假设中转站在 $x$ ，你要算什么？算完后咋办？

如果中转站在 $x$ ，则俩人需要走最短路到 $x$ ，再从 $x$ 走最短路回到分别的起点。

于是关键分别是从 $a,b$ 出发的最短路和到 $a,b$ 的最短路。前者是典型的最短路问题，后者可以对整个图的反图求最短路，也能解决。

但这里还有一件事儿，就是分别可以有 $k$ 条边免权值。

所以考虑状态——用了 $i$ 条免费边后在 $u$ 节点的最短路。则 $i$ 相同的情况下有 $m$ 条边，而 $m$ 条边可以以 $0$ 的成本从 $(i,u)$ 转移到 $(i+1,v)$ 。

这样就是分层图，在这个图中跑最短路。

得到 $4$ 个部分的最短路后，考虑枚举中转站 $x$ ，则我们要求前后两段的免费边总数不超过 $k$ ，我们可以维护后缀最小值后，对于每个结点 $\mathcal{O}(k)$ 计算出结果。

这题设计的最短路特别多，比较推荐实现成函数后再调用。

时间复杂度为 $\mathcal{O}(mk+nk\log(nk))$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, m = MII()
    a, b, k = MII()

    path = [[] for _ in range(n)]
    rev_path = [[] for _ in range(n)]

    for _ in range(m):
        u, v, w = MII()
        path[u].append(w * n + v)
        rev_path[v].append(w * n + u)

    def f(d, u, layer):
        return (d * n + u) * (k + 1) + layer

    def shortest_path(graph, start):
        dis = [[inf] * n for _ in range(k + 1)]
        dis[0][start] = 0

        pq = [f(0, start, 0)]

        while pq:
            msk = heappop(pq)
            msk, layer = divmod(msk, k + 1)
            d, u = divmod(msk, n)

            if dis[layer][u] == d:
                for emsk in graph[u]:
                    w, v = divmod(emsk, n)

                    if dis[layer][v] > dis[layer][u] + w:
                        dis[layer][v] = dis[layer][u] + w
                        heappush(pq, f(dis[layer][v], v, layer))

                    if layer < k and dis[layer + 1][v] > dis[layer][u]:
                        dis[layer + 1][v] = dis[layer][u]
                        heappush(pq, f(dis[layer + 1][v], v, layer + 1))

        for i in range(1, k + 1):
            for u in range(n):
                dis[i][u] = fmin(dis[i][u], dis[i - 1][u])

        return dis

    def solve(start):
        v1 = shortest_path(path, start)
        v2 = shortest_path(rev_path, start)

        ans = [inf] * n

        for i in range(k + 1):
            for u in range(n):
                ans[u] = fmin(ans[u], v1[i][u] + v2[k - i][u])

        return ans

    wa = solve(a)
    wb = solve(b)

    ans = inf
    chosen = -1

    for u in range(n):
        if u != a and u != b and wa[u] + wb[u] < ans:
            ans = wa[u] + wb[u]
            chosen = u

    if ans < inf: print(chosen, ans)
    else: print('>:(')
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m, a, b, k, inf = 1e9;
	cin >> n >> m >> a >> b >> k;

	vector<vector<pair<int, int>>> path(n), rev_path(n);

	while (m --) {
		int u, v, w;
		cin >> u >> v >> w;

		path[u].emplace_back(v, w);
		rev_path[v].emplace_back(u, w);
	}

	auto shortest_path = [&] (vector<vector<pair<int, int>>> &graph, int start) -> vector<vector<int>> {
		vector<vector<int>> dis(k + 1, vector<int>(n, inf));
		dis[0][start] = 0;

		priority_queue<array<int, 3>, vector<array<int, 3>>, greater<array<int, 3>>> pq;

		pq.push({0, 0, start});

		while (!pq.empty()) {
			auto [d, layer, u] = pq.top(); pq.pop();

			if (dis[layer][u] == d) {
				for (auto &[v, w]: graph[u]) {
					if (dis[layer][v] > dis[layer][u] + w) {
						dis[layer][v] = dis[layer][u] + w;
						pq.push({dis[layer][v], layer, v});
					}
					if (layer + 1 <= k && dis[layer + 1][v] > dis[layer][u]) {
						dis[layer + 1][v] = dis[layer][u];
						pq.push({dis[layer + 1][v], layer + 1, v});
					}
				}
			}
		}

		for (int i = 1; i <= k; i ++) {
			for (int u = 0; u < n; u ++) {
				dis[i][u] = min(dis[i][u], dis[i - 1][u]);
			}
		}

		return dis;
	};

	auto solve = [&] (int start) -> vector<int> {
		auto v1 = shortest_path(path, start);
		auto v2 = shortest_path(rev_path, start);

		vector<int> ans(n, inf);

		for (int i = 0; i <= k; i ++) {
			for (int u = 0; u < n; u ++) {
				ans[u] = min(ans[u], v1[i][u] + v2[k - i][u]);
			}
		}

		return ans;
	};

	auto wa = solve(a), wb = solve(b);

	pair<int, int> ans = {inf, -1};

	for (int i = 0; i < n; i ++) if (i != a && i != b) ans = min(ans, {wa[i] + wb[i], i});

	if (ans.first < inf) cout << ans.second << ' ' << ans.first;
	else cout << ">:(";

	return 0;
}
```

**提示 1：** DP，转移并不多。

考虑某一段结尾是 $i$ 的序列有 $dp[i]$ 个。如何计算它呢？

考虑最后一段的长度，只可能是 $2^0,2^1,2^2,\dots$ ，而这个序列增长很快，所以最后一段的长度总共只有 $\mathcal{O}(\log n)$ 种选择，将对应 $dp[i-len]$ 个方案转移过来就好。

注意 $dp[0]=2$ ，因为开头可以是两种情况的任何一种。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    mod = 10 ** 9 + 7

    dp = [0] * (n + 1)
    dp[0] = 2

    for i in range(1, n + 1):
        v = 1
        while i >= v:
            dp[i] += dp[i - v]
            v *= 2
        dp[i] %= mod

    print(dp[n])
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, mod = 1e9 + 7;
	cin >> n;

	vector<int> dp(n + 1, 0);
	dp[0] = 2;

	for (int i = 1; i <= n; i ++) {
		for (int j = 1; j <= i; j <<= 1) {
			dp[i] = (dp[i] + dp[i - j]) % mod;
		}
	}

	cout << dp[n];

	return 0;
}
```

**提示 1：** 最短路，为啥可以用？边权如何？实现如何？

考虑整条路径。包含三个部分：从海岸线到第一个伞，从伞到伞（可能很多次），从伞到路边。

第一部分，只要我们知道用的是哪个圆，则相当于求圆内任意一点到直线的距离。分情况：如果有公共点，即圆心到直线的距离不超过半径，这个答案是 $0$ ；否则答案是圆心到直线的距离减去半径。

从伞到路边的过程也是类似的。

中间伞之间的路径，假设有一段是从一个圆到另一个圆，则最优的走法是沿着圆心的连线走。这是因为如果两圆形有公共点，则这部分权值为 $0$ ，否则距离不小于两个圆心的距离减去两个半径，因为圆心之间的距离小于等于圆上两点的距离加上两个半径（两点之间线段最短）。

当然，如果重新规划的路径经过了别的圆，我们就继续优化新的分割出来的路，最后走的一定是圆心之间连线的路。

于是我们得到了一个完全图——所有伞之间的边权完全确定，海到伞、伞到路的边权也确定，在这个稠密图上跑最短路就好。

稠密图使用堆优化的 Dijkstra 会多一个 log 复杂度，不带堆优化可以复杂度更优，实在不清楚可以看后面的代码。

时间复杂度为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, h = MII()

    if n == 0: print(h)
    else:
        xs = []
        ys = []
        rs = []

        for _ in range(n):
            x, y, r = MII()
            xs.append(x)
            ys.append(y)
            rs.append(r)

        dis = [fmax(ys[i] - rs[i], 0) for i in range(n)]
        vis = [0] * n

        def f(i, j):
            return math.sqrt((xs[i] - xs[j]) * (xs[i] - xs[j]) + (ys[i] - ys[j]) * (ys[i] - ys[j]))

        for _ in range(n):
            chosen = -1
            for idx in range(n):
                if vis[idx] == 0 and (chosen == -1 or dis[idx] < dis[chosen]):
                    chosen = idx

            vis[chosen] = 1
            for i in range(n):
                dis[i] = fmin(dis[i], dis[chosen] + fmax(0, f(chosen, i) - rs[chosen] - rs[i]))

        ans = min(dis[i] + fmax(0, h - ys[i] - rs[i]) for i in range(n))
        print(f'{ans:.15f}')
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, h;
	cin >> n >> h;

	if (!n) return cout << h, 0;

	vector<array<int, 3>> circles(n);

	for (auto &[x, y, r]: circles) cin >> x >> y >> r;

	vector<long double> dis(n);

	for (int i = 0; i < n; i ++) {
		auto [x, y, r] = circles[i];
		dis[i] = max(0, y - r);
	}

	vector<bool> vis(n, false);

	for (int i = 0; i < n; i ++) {
		int chosen = -1;
		for (int j = 0; j < n; j ++) {
			if (!vis[j] && (chosen == -1 || dis[j] < dis[chosen])) {
				chosen = j;
			}
		}

		vis[chosen] = 1;

		for (int j = 0; j < n; j ++) {
			auto [x1, y1, r1] = circles[chosen];
			auto [x2, y2, r2] = circles[j];
			dis[j] = min(dis[j], dis[chosen] + max((long double)0, hypotl(x1 - x2, y1 - y2) - r1 - r2));
		}
	}

	long double ans = h;

	for (int i = 0; i < n; i ++) {
		auto [x, y, r] = circles[i];
		ans = min(ans, dis[i] + max(0, h - (y + r)));
	}

	cout << fixed << setprecision(15) << ans;

	return 0;
}
```

**提示 1：** 拆贡献，每一部分贡献如何？

首先，一个数组的段落数，等于 $1$ 加上相邻两项不同的出现次数。

于是只需求相邻两项不同的期望次数。

如果 $k\gt 0$ ，则任意一组相邻元素都至少有一个是随机出来的，因此不同的概率总是 $\frac{x-1}{x}$ ，而为了算出相邻两项不同的总出现次数，可以用期望可加性，用总数乘以这个概率。

每次间隔数量刚好乘 $2$ ，所以最后有 $(n-1)\times 2^k$ 个间隔，乘以对应概率就是这部分答案。

当然，相对容易忽略的 $k=0$ 的情况，此时数组不变，统计一下就行。

时间复杂度为 $\mathcal{O}(n)$ 或 $\mathcal{O}(\log k)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n, x, k = MII()
    nums = LII()

    mod = 10 ** 9 + 7

    if k:
        total = (n - 1) * pow(2, k, mod) % mod
        print((total + 1 - total * pow(x, -1, mod)) % mod)

    else:
        print(sum(nums[i] != nums[i - 1] for i in range(1, n)) + 1)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, x, k;
	cin >> n >> x >> k;

	vector<int> nums(n);

	for (auto &v: nums) cin >> v;

	int mod = 1e9 + 7;

	if (k) {
		int total = (n - 1) * quickPow(2, k, mod) % mod;
		cout << ((x - 1) * quickPow(x, mod - 2, mod) % mod * total % mod + 1) % mod;
	}
	else {
		int ans = 1;
		for (int i = 1; i < n; i ++) ans += (nums[i] != nums[i - 1]);
		cout << ans;
	}

	return 0;
}
