			vector<long long> tmp(n, -inf);
			vector<vector<long long>> transition(k, vector<long long>(k, -inf));

			for (int i = 0; i < k; i ++) {
				auto [s, e] = skis[i];
				tmp[e] = 0;

				for (auto &u: topo) {
					for (auto &v: path[u]) {
