			for (int i = 0; i < 29; i ++) {
				for (int u = 0; u < k; u ++) {
					for (int v = 0; v < k; v ++) {
						for (int w = 0; w < k; w ++) {
							nth_transition[i + 1][f(u, w)] = max(nth_transition[i + 1][f(u, w)], nth_transition[i][f(u, v)] + nth_transition[i][f(v, w)]);
						}
					}
				}
			}

			int ans = 2;

			for (int i = 29; i >= 0; i --) {
				bool flg = true;

				for (int u = 0; u < k; u ++) {
					for (int v = 0; v < k; v ++) {
						if (v0[u] + nth_transition[i][f(u, v)] + v1[v] >= target) {
