**提示 1：** 枚举右端点，哪些信息重要？

**提示 2：** 右侧移左端点，你如何更新必要的信息？

首先，对于右端点，各个位重要的信息有哪些呢？

就是这一位前一次 $0/1$ 出现的位置，左端点是否不超过两者的最小值决定了这一位是不是 mixed bit 。

这些位置更新后如何找到左端点呢？对于递增的右端点，左端点是递增的。因此我们可以在一个长度为 $n$ 数组中标记，维护 $[l,r]$ 之间标记的 $1$ 的个数，超过的情况下不断右移左端点即可。

因为双指针只擅长解决大于 / 小于某个范围之类的问题，所以用不超过 $k$ 的子数组个数减去 $k-1$ 的子数组个数即可。

时间复杂度为 $\mathcal{O}(nm)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n, m, k = MII()
        nums = LII()

        def f(x):
            if x < 0:
                return 0

            ans = 0

            last_0 = [-1] * m
            last_1 = [-1] * m
            vis = [0] * n

            l = 0
            cur = 0

            for r in range(n):
                for i in range(m):
                    pos = fmin(last_0[i], last_1[i])
                    if l <= pos <= r:
                        cur -= 1
                    if pos >= 0:
                        vis[pos] -= 1

                    if nums[r] >> i & 1:
                        last_1[i] = r
                    else:
                        last_0[i] = r

                    pos = fmin(last_0[i], last_1[i])
                    if l <= pos <= r:
                        cur += 1
                    if pos >= 0:
                        vis[pos] += 1

                while cur > x:
                    cur -= vis[l]
                    l += 1

                ans += r - l + 1

            return ans

        outs.append(f(k) - f(k - 1))

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n, m, k;
		cin >> n >> m >> k;

		vector<int> nums(n);
		for (auto &x: nums) cin >> x;

		auto f = [&] (int x) -> long long {
			if (x < 0) return 0;

			long long ans = 0;
			vector<int> last_0(m, -1), last_1(m, -1), vis(n, 0);

			int l = 0, cur = 0;

			for (int r = 0; r < n; r ++) {
				for (int i = 0; i < m; i ++) {
					{
						int pos = min(last_0[i], last_1[i]);
						if (pos >= l && pos <= r) cur --;
						if (pos >= 0) vis[pos] --;
					}

					if (nums[r] >> i & 1) last_1[i] = r;
					else last_0[i] = r;

					{
						int pos = min(last_0[i], last_1[i]);
						if (pos >= l && pos <= r) cur ++;
						if (pos >= 0) vis[pos] ++;
					}
				}

				while (cur > x) cur -= vis[l ++];
				ans += r - l + 1;
			}

			return ans;
		};

		cout << f(k) - f(k - 1) << '\n';
	}

	return 0;
}
