int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, q;
	cin >> n >> q;

	vector<vector<long long>> updates(n + 1);

	while (q --) {
		int f, s, c;
		cin >> f >> s >> c;

		s = gcd(s, n);
		if (updates[s].empty())
			updates[s] = vector<long long>(s, 0);
		updates[s][(f - 1) % s] += c;
	}

