**提示 1：** 模拟。

考虑清楚模拟什么。

要维护的操作：删去某个 $id$ 的元素，尾部插入元素，获取并删去头部元素，反转。

这些操作用链表搭配一个查询元素对应链表结点的哈希表即可。

删去元素——将前后元素拼接。

尾部插入元素——根据此时是否链表反转，将元素插入开头 / 结尾。

获取头部元素——根据此时是否链表反转，获取开头 / 结尾元素。

反转——打标记。

整体需要两个结构，一个维护全队列，一个维护 $state=0$ 的队列。还可能涉及到元素是否在链表内的判断（用哈希表即可），链表是否为空的判断。这些也都是容易的。

维护的东西相近所以考虑构造类就行。

时间复杂度为 $\mathcal{O}(n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    class LinkedList:
        def __init__(self, n):
            self.head = 0
            self.tail = 1

            self.nxt = [-1] * (n + 5)
            self.prv = [-1] * (n + 5)
            self.tags = [0] * (n + 5)

            self.nxt[0] = 1
            self.prv[1] = 0

            self.pos = {}
            self.sz = 0
            self.flg = False
            self.pt = 2

        def check(self, idx):
            return idx in self.pos

        def size(self):
            return self.sz

        def insert(self, idx):
            if self.flg:
                self.prv[self.pt] = self.head
                self.nxt[self.pt] = self.nxt[self.head]
            else:
                self.prv[self.pt] = self.prv[self.tail]
                self.nxt[self.pt] = self.tail

            self.nxt[self.prv[self.pt]] = self.pt
            self.prv[self.nxt[self.pt]] = self.pt

            self.tags[self.pt] = idx
            self.pos[idx] = self.pt

            self.pt += 1
            self.sz += 1

        def delete(self, idx):
            p = self.pos[idx]
            del self.pos[idx]

            self.prv[self.nxt[p]] = self.prv[p]
            self.nxt[self.prv[p]] = self.nxt[p]

            self.sz -= 1

        def get_head(self):
            return self.tags[self.prv[self.tail] if self.flg else self.nxt[self.head]]

        def reverse(self):
            self.flg = not self.flg

        def output(self):
            ans = []

            if self.flg:
                cur = self.tail
                while self.prv[cur] != self.head:
                    cur = self.prv[cur]
                    ans.append(self.tags[cur])
            else:
                cur = self.head
                while self.nxt[cur] != self.tail:
                    cur = self.nxt[cur]
                    ans.append(self.tags[cur])

            return ans

    t = II()
    outs = []

    rnd = random.getrandbits(30)

    for _ in range(t):
        n, m, k = MII()

        idxs = [0] * n
        states = [0] * n

        for i in range(n):
            idxs[i], states[i] = MII()
            idxs[i] ^= rnd

        reverses = [0] * n
        if k:
            for idx in GMI():
                reverses[idx] = 1

        total = LinkedList(n)
        broken = LinkedList(n)

        for i in range(n):
            if total.check(idxs[i]):
                total.delete(idxs[i])
                if broken.check(idxs[i]):
                    broken.delete(idxs[i])

                total.insert(idxs[i])
                if not states[i]:
                    broken.insert(idxs[i])

            elif total.size() < m:
                total.insert(idxs[i])
                if not states[i]:
                    broken.insert(idxs[i])

            elif broken.size():
                idx = broken.get_head()
                total.delete(idx)
                broken.delete(idx)

                total.insert(idxs[i])
                if not states[i]:
                    broken.insert(idxs[i])

            elif states[i]:
                idx = total.get_head()
                total.delete(idx)

                total.insert(idxs[i])
                if not states[i]:
                    broken.insert(idxs[i])

            if reverses[i]:
                total.reverse()
                broken.reverse()

        ans = total.output()
        outs.append(str(len(ans)))
        outs.append(' '.join(str(x ^ rnd) for x in ans))

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
struct ListNode {
	public:
		explicit ListNode(int n) {
			head = 0;
			tail = 1;

			nxt = vector<int>(n + 5, -1);
			prv = vector<int>(n + 5, -1);
			tag = vector<int>(n + 5, 0);

			nxt[0] = 1;
			prv[1] = 0;

			sz = 0, flg = false, pt = 2;
		}

		bool check(int idx) {return pos.find(idx) != pos.end();}

		int size() {return sz;}

		void insert(int idx) {
			if (flg) {
				prv[pt] = head;
				nxt[pt] = nxt[head];
			}
			else {
				prv[pt] = prv[tail];
				nxt[pt] = tail;
			}

			nxt[prv[pt]] = pt;
			prv[nxt[pt]] = pt;

			tag[pt] = idx;
			pos[idx] = pt;

			pt ++, sz ++;
		}

		void remove(int idx) {
			int p = pos[idx];
			pos.erase(idx);

			prv[nxt[p]] = prv[p];
			nxt[prv[p]] = nxt[p];

			sz --;
		}

		int get_head() {return tag[flg ? prv[tail] : nxt[head]];}

		void reverse() {flg = !flg;}

		void output(int rnd) {
			cout << sz << '\n';

			if (flg) {
				int cur = tail;
				while (prv[cur] != head) {
					cur = prv[cur];
					cout << (tag[cur] ^ rnd) << ' ';
				}
			}
			else {
				int cur = head;
				while (nxt[cur] != tail) {
					cur = nxt[cur];
					cout << (tag[cur] ^ rnd) << ' ';
				}
			}

			cout << '\n';
		}

	private:
		int head, tail, sz, pt;
		bool flg;
		vector<int> nxt, prv, tag;
		unordered_map<int, int> pos;
};

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, rnd = rng();
	cin >> t;

	while (t --) {
		int n, m, k;
		cin >> n >> m >> k;

		vector<int> idxs(n), states(n);

		for (int i = 0; i < n; i ++) {
			cin >> idxs[i] >> states[i];
			idxs[i] ^= rnd;
		}

		vector<int> reverses(n, 0);
		while (k --) {
			int idx; cin >> idx;
			reverses[idx - 1] = 1;
		}

		auto total = ListNode(n);
		auto broken = ListNode(n);

		for (int i = 0; i < n; i ++) {
			if (total.check(idxs[i])) {
				total.remove(idxs[i]);
				if (broken.check(idxs[i])) broken.remove(idxs[i]);
				total.insert(idxs[i]);
				if (!states[i]) broken.insert(idxs[i]);
			}
			else if (total.size() < m) {
				total.insert(idxs[i]);
				if (!states[i]) broken.insert(idxs[i]);
			}
			else if (broken.size()) {
				int idx = broken.get_head();
				total.remove(idx);
				broken.remove(idx);
				total.insert(idxs[i]);
				if (!states[i]) broken.insert(idxs[i]);
			}
			else if (states[i]) {
				int idx = total.get_head();
				total.remove(idx);
				total.insert(idxs[i]);
				if (!states[i]) broken.insert(idxs[i]);
			}

			if (reverses[i]) total.reverse(), broken.reverse();
		}

		total.output(rnd);
	}

	return 0;
}
```

**提示 1：** 从小到大考虑每个位置拿什么分。

我们先记录等于 $k$ 的 $a_i$ 有多少个。

顺序遍历 $k$ 。记当前还可以用的 $a_i$ ，也就是小于当前 $k$ 并且还没拿到 $w_i$ 收益的 $a_i$ 的数量为 $x$ 。

当我们遍历到位置 $k+1$ 时候，我们先更新 $x$ ，加上等于 $k+1$ 的 $a_i$ 的数量。

而如果此时 $x\gt 0$ ，我们直接获取 $w_i$ ，并将 $x$ 更新为 $x-1$ 。

如果 $x=0$ 呢？我们可以尝试将之前获取的一个 $w_i$ 替换为当前权值，于是需要用一个最小堆提取这个最小值。这里也就是一个反悔贪心。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n = II()
        v1 = LII()
        v2 = LII()

        cnt = [0] * n

        for x in v1:
            if x <= n:
                cnt[x - 1] += 1

        to_fill = 0

        total = 0
        pq = []

        for i in range(n):
            if cnt[i]:
                to_fill += cnt[i] - 1
                total += v2[i]
                heappush(pq, v2[i])

            elif to_fill:
                to_fill -= 1
                total += v2[i]
                heappush(pq, v2[i])

            elif pq and pq[0] < v2[i]:
                total += v2[i] - pq[0]
                heapreplace(pq, v2[i])

        outs.append(total)

    print('\n'.join(map(str, outs)))
