int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		string s;
		cin >> n >> s;

		auto check1 = [&] () -> bool {
			for (auto &c: s) if (c == '0') return false;
			return true;
		};

		auto check2 = [&] () -> bool {
			for (int i = 0; i < n; i ++) {
				if (s[i] - '0' == i % 2) {
					return false;
				}
			}
			return true;
		};

		auto check3 = [&] () -> bool {
			if (s[0] == '0') return false;
			for (int i = 1; i < n; i ++)
				if (s[i] == '1') return false;
			return true;
		};

		auto check4 = [&] () -> bool {
			if (s[0] == '0' || s[n - 1] == '0') return false;
			for (int i = 1; i < n - 1; i ++)
				if (s[i] == '1') return false;
			return true;
		};

		if (check1()) cout << string(n, 'a') << '\n';
		else if (check2()) {
