**提示 1：** 考虑能发送到 $v$ 的点集是什么，如何更新。

能发送到 $v$ 的点需要时 $v$ 的祖先，且两者之间的路径经过的百年全的极差不超过 $a_v$ 。

而越往上找祖先，极差是单调不减的。所以相当于是 $v$ 出发到最浅的一个满足条件的结点的路径上，所有的点都满足条件，也就是对这些点的答案更新 $+1$ 操作。

怎么找那个浅的点呢？可以倍增。依次尝试跳 $2^{19},2^{18},\dots,2^0$ 步，这样就可以找到对应的点了。

怎么更新呢？是树上路径的 $+1$ 操作，因此可以差分更新。不熟悉的可以搜索树上差分。

时间复杂度为 $\mathcal{O}(n\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    inf = 10 ** 9

    for _ in range(t):
        n = II()
        nums = LII()

        parent = [[-1] * n for _ in range(20)]
        mi = [[0] * n for _ in range(20)]
        ma = [[0] * n for _ in range(20)]

        for i in range(1, n):
            p, w = MII()
            p -= 1
            parent[0][i] = p
            mi[0][i] = w
            ma[0][i] = w

        for i in range(19):
            for j in range(n):
                if parent[i][j] != -1:
                    parent[i + 1][j] = parent[i][parent[i][j]]
                    mi[i + 1][j] = fmin(mi[i][j], mi[i][parent[i][j]])
                    ma[i + 1][j] = fmax(ma[i][j], ma[i][parent[i][j]])

        ans = [0] * n

        for i in range(n):
            cur = i
            cur_mi = inf
            cur_ma = -inf

            for j in range(19, -1, -1):
                if parent[j][cur] == -1: continue

                ncur_mi = fmin(cur_mi, mi[j][cur])
                ncur_ma = fmax(cur_ma, ma[j][cur])

                if ncur_ma - ncur_mi <= nums[i]:
                    cur = parent[j][cur]
                    cur_mi = ncur_mi
                    cur_ma = ncur_ma

            ans[i] += 1
            if cur: ans[parent[0][cur]] -= 1

        for i in range(n - 1, 0, -1):
            ans[parent[0][i]] += ans[i]

        outs.append(' '.join(map(str, ans)))

    print('\n'.join(outs))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, inf = 1e9;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<int> nums(n);
		for (auto &v: nums) cin >> v;

		vector<vector<int>> parent(20, vector<int>(n, -1));
		vector<vector<int>> mi(20, vector<int>(n));
		vector<vector<int>> ma(20, vector<int>(n));

		for (int i = 1; i < n; i ++) {
			int p, w;
			cin >> p >> w;
			p --;
			parent[0][i] = p;
			mi[0][i] = w;
			ma[0][i] = w;
		}

		for (int i = 0; i < 19; i ++) {
			for (int j = 0; j < n; j ++) {
				if (parent[i][j] != -1) {
					parent[i + 1][j] = parent[i][parent[i][j]];
					mi[i + 1][j] = min(mi[i][j], mi[i][parent[i][j]]);
					ma[i + 1][j] = max(ma[i][j], ma[i][parent[i][j]]);
				}
			}
		}

		vector<int> ans(n, 0);

		for (int i = 0; i < n; i ++) {
			int cur = i, cur_mi = inf, cur_ma = -inf;

			for (int j = 19; j >= 0; j --) {
				if (parent[j][cur] == -1) continue;

				int ncur_mi = min(cur_mi, mi[j][cur]);
				int ncur_ma = max(cur_ma, ma[j][cur]);

				if (ncur_ma - ncur_mi <= nums[i]) {
					cur = parent[j][cur];
					cur_mi = ncur_mi;
					cur_ma = ncur_ma;
				}
			}

			ans[i] ++;
			if (cur) ans[parent[0][cur]] --;
		}

		for (int i = n - 1; i > 0; i --) ans[parent[0][i]] += ans[i];

		for (int i = 0; i < n; i ++) cout << ans[i] << " \n"[i == n - 1];
	}

	return 0;
}
