**提示 1：** 将曼哈顿距离转化为切比雪夫距离。

**提示 2：** 哪些点有必要删？

首先，我们可以进行坐标变换 $(x,y)\to (x-y,x+y)$ ，将原问题转化为切比雪夫距离。

而事实上，我们只需求横坐标跨度和纵坐标跨度的最大值。

因此，我们只可能在纵坐标最大 / 最小的两个点以及横坐标最大 / 最小的两个点形成的集合中，选取两个点删掉。

这里的方案并不多，我们直接暴力枚举，看剩余的点对应的答案，取这个答案的最小值即可。

时间复杂度为 $\mathcal{O}(n)$ ，如果你用线性方式求前两大前两小。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    inf = 4 * 10 ** 9

    for _ in range(t):
        n = II()
        xs = []
        ys = []

        for _ in range(n):
            x, y = MII()
            xs.append(x - y)
            ys.append(x + y)

        if n <= 3: outs.append(0)
        else:
            st1 = sorted(range(n), key=lambda x: xs[x])
            st2 = sorted(range(n), key=lambda x: ys[x])

            idxs = st1[:2] + st1[-2:] + st2[:2] + st2[-2:]

            ans = inf

            for i in range(8):
                for j in range(i):
                    i1 = idxs[i]
                    i2 = idxs[j]

                    mi_x = inf
                    ma_x = -inf

                    mi_y = inf
                    ma_y = -inf

                    for idx in range(n):
                        if idx != i1 and idx != i2:
                            mi_x = fmin(mi_x, xs[idx])
                            ma_x = fmax(ma_x, xs[idx])

                            mi_y = fmin(mi_y, ys[idx])
                            ma_y = fmax(ma_y, ys[idx])

                    ans = fmin(ans, fmax(ma_x - mi_x, ma_y - mi_y))

            outs.append(ans)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, inf = 2e9;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		vector<pair<int, int>> pts;

		for (int i = 0; i < n; i ++) {
			int a, b;
			cin >> a >> b;
			pts.emplace_back(a + b, a - b);
		}

		if (n <= 3) cout << 0 << '\n';
		else {
			vector<int> order1(n), order2(n);

			iota(order1.begin(), order1.end(), 0);
			iota(order2.begin(), order2.end(), 0);

			sort(order1.begin(), order1.end(), [&] (int i, int j) {
				return pts[i].first < pts[j].first;
			});
			sort(order2.begin(), order2.end(), [&] (int i, int j) {
				return pts[i].second < pts[j].second;
			});

			vector<int> idxs;

			idxs.emplace_back(order1[0]);
			idxs.emplace_back(order1[1]);
			idxs.emplace_back(order1[n - 2]);
			idxs.emplace_back(order1[n - 1]);

			idxs.emplace_back(order2[0]);
			idxs.emplace_back(order2[1]);
			idxs.emplace_back(order2[n - 2]);
			idxs.emplace_back(order2[n - 1]);

			long long ans = 4e9;

			for (int i = 0; i < 8; i ++) {
				for (int j = 0; j < i; j ++) {
					int i1 = idxs[i], i2 = idxs[j];

					long long mi_x = inf, ma_x = -inf;
					long long mi_y = inf, ma_y = -inf;

					for (int idx = 0; idx < n; idx ++) {
						if (idx != i1 && idx != i2) {
							long long x = pts[idx].first;
							long long y = pts[idx].second;
							mi_x = min(mi_x, x);
							ma_x = max(ma_x, x);
							mi_y = min(mi_y, y);
							ma_y = max(ma_y, y);
						}
					}

					ans = min(ans, max(ma_x - mi_x, ma_y - mi_y));
				}
			}

			cout << ans << '\n';
		}
	}

	return 0;
}
```

**提示 1：** 每个结点不被计入答案的条件是什么？

每个结点不被计入答案，当且仅当区间内存在一个右侧的位置比它大，且存在一个左侧的位置比它大。

所以对于每个元素，我们找到左侧和右侧第一个比它大的元素。

这样只要查询的区间包含了这个区间，则这个点不计入查询区间的答案中。

于是原问题转化为一个经典问题：给定一系列区间，查询 $l,r$ ，问 $[l,r]$ 包含了多少区间。

可以离线来做，我们从右到左枚举所有的 $l$ ，把所有左端点大于等于 $l$ 的区间纳入考虑范围，则此时 $l$ 对应的查询，即当前考虑的区间中，有多少个右端点不超过 $r$ ，这就很容易用树状数组维护了。

时间复杂度为 $\mathcal{O}((n+q)\log n)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    for _ in range(t):
        n, q = MII()
        nums = LII()

        left = [-1] * n
        stk = [-1]

        for i in range(n):
            while stk[-1] != -1 and nums[stk[-1]] <= nums[i]:
                stk.pop()
            left[i] = stk[-1]
            stk.append(i)

        right = [n] * n
        stk = [n]

        for i in range(n - 1, -1, -1):
            while stk[-1] != n and nums[stk[-1]] <= nums[i]:
                stk.pop()
            right[i] = stk[-1]
            stk.append(i)

        updates = [[] for _ in range(n)]

        for i in range(n):
            if left[i] >= 0 and right[i] < n:
                updates[left[i]].append(right[i])

        queries = [[] for _ in range(n)]

        for i in range(q):
            l, r = GMI()
            queries[l].append((i, r))

        ans = [0] * q

        fen = FenwickTree(n)

        for l in range(n - 1, -1, -1):
            for r in updates[l]:
                fen.add(r, 1)

            for i, r in queries[l]:
                ans[i] = r - l + 1 - fen.rsum(0, r)

        outs.append('\n'.join(map(str, ans)))

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n, q;
		cin >> n >> q;

		vector<int> nums(n);
		for (auto &x: nums) cin >> x;

		vector<int> left(n, -1), right(n, n);
		vector<int> stk;

		stk = {-1};

		for (int i = 0; i < n; i ++) {
			while (stk.back() != -1 && nums[stk.back()] <= nums[i])
				stk.pop_back();
			left[i] = stk.back();
			stk.emplace_back(i);
		}

		stk = {n};

		for (int i = n - 1; i >= 0; i --) {
			while (stk.back() != n && nums[stk.back()] <= nums[i])
				stk.pop_back();
			right[i] = stk.back();
			stk.emplace_back(i);
		}

		vector<vector<int>> updates(n);

		for (int i = 0; i < n; i ++) {
			if (left[i] >= 0 && right[i] < n) {
				updates[left[i]].emplace_back(right[i]);
			}
		}

		vector<vector<pair<int, int>>> queries(n);

		for (int i = 0; i < q; i ++) {
			int l, r;
			cin >> l >> r;
			queries[l - 1].emplace_back(i, r - 1);
		}

		vector<int> ans(q);
		atcoder::fenwick_tree<int> fen(n);

		for (int l = n - 1; l >= 0; l --) {
			for (auto &r: updates[l]) fen.add(r, 1);
			for (auto &[i, r]: queries[l]) ans[i] = r - l + 1 - fen.sum(0, r + 1);
		}

		for (auto &x: ans) cout << x << '\n';
	}

	return 0;
}
```

**提示 1：** 用相近的查询推出一些东西。

如果我们的查询太没有章法，显然就很不好做了。

考虑查询长度为 $2,3,\dots, n$ 的前缀，这样次数恰好满足要求。

我们可以用 $n,n-1$ 的查询，得到最后一项比前面的多少项小，也就确认了最后一项到底是啥，也可以在备选数字中去掉它。

于是问题转化为 $n-1$ 的子问题，如此不断确定第 $i$ 项是前 $i$ 项中第几大的，也就能确定其取值了。

时间复杂度为 $\mathcal{O}(n^2)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    def query(idxs):
        print('?', len(idxs), *idxs, flush=True)
        return II()

    def answer(p):
        print('!', *p, flush=True)

    t = II()

    for _ in range(t):
        n = II()
        cur = 0

        ans = [0] * n
        ans[0] = 1

        for i in range(2, n + 1):
            ncur = query(list(range(1, i + 1)))
            val = i - (ncur - cur)

            for j in range(i):
                if ans[j] >= val:
                    ans[j] += 1
            ans[i - 1] = val

            cur = ncur

        answer(ans)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t;
	cin >> t;

	while (t --) {
		int n;
		cin >> n;

		long long cur = 0;
		vector<int> ans(n, 0);

		ans[0] = 1;

		for (int i = 2; i <= n; i ++) {
			cout << "? " << i;
			for (int j = 1; j <= i; j ++) cout << ' ' << j;
			cout << endl;

			long long ncur;
			cin >> ncur;

			int v = i - (ncur - cur);

			for (int j = 0; j < i; j ++) {
				if (ans[j] >= v) {
					ans[j] ++;
				}
			}
			ans[i - 1] = v;

			cur = ncur;
		}

		cout << "!";
		for (auto &x: ans) cout << ' ' << x;
		cout << endl;
	}

	return 0;
}
```

**提示 1：** 先考虑固定的 $k$ 个数如何求解。剩下的好像很好办。

如果有固定的 $k$ 个数，MST 边权和怎么求呢？

$LSB(|a_u-a_v|)$ 也就是 $a_u, a_v$ 最低的不同的位。

如果这 $k$ 个数的最低的 $i$ 位都相同，则 $LSB$ 肯定取不到那个位。

所以 $LSB(|a_u-a_v|)$ 最小只能取到最小的有不同的位，设为 $x$ 。

而我们根据这一位把数字分为两类，则两类间的边边权都是 $x$ 。

而这些 $x$ 边权的边已经能形成一个连通图了，因此 MST 的边权和是 $(k-1)x$ 。

所以综上，我们只需找到一个 $k$ 元子集，使得其最低的不同的位尽可能高。

我们可以二分这一个位 $x$ ，这样我们只需统计更低的位的各种数字的出现频率，看是否有不小于 $k$ 的，如果有， $x$ 就是可行的了。

时间复杂度为 $\mathcal{O}(n\log\log M)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    t = II()
    outs = []

    rnd = random.getrandbits(30)

    for _ in range(t):
        n, k = MII()
        nums = LII()

        l = 0
        r = 29

        while l <= r:
            mid = (l + r) // 2

            msk = (1 << mid) - 1
            cnt = Counter()

            for x in nums:
                cnt[(x & msk) ^ rnd] += 1

            if max(cnt.values()) >= k: l = mid + 1
            else: r = mid - 1

        outs.append((k - 1) << r)

    print('\n'.join(map(str, outs)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int t, rnd = rng();
	cin >> t;

	while (t --) {
		int n, k;
		cin >> n >> k;

		vector<int> nums(n);
		for (auto &v: nums) cin >> v;

		int l = 0, r = 29;

		while (l <= r) {
			int mid = (l + r) / 2;

			int msk = (1 << mid) - 1;
			unordered_map<int, int> cnt;

			for (auto &v: nums)
				cnt[(v & msk) ^ rnd] ++;

			int max_cnt = 0;
			for (auto &[k, v]: cnt) max_cnt = max(max_cnt, v);

			if (max_cnt >= k) l = mid + 1;
			else r = mid - 1;
		}

		cout << ((long long)(k - 1) << r) << '\n';
	}

	return 0;
}
```

**提示 1：** 并非几何题。精度要求低，数据范围小。

先看提示。

我们不用任何几何知识。

我们在 $-10\leq x\leq 20,-10\leq x\leq 20$ 的范围内进行随机采样，则其在图形内的概率是面积 / 900 。

所以我们采样足够多次时，频率可以用于估计概率，也就是类似蒙特卡洛的方法估计面积。

具体需要多少次，可以使用中心极限定理推一下，用正态分布进行最后估计。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    n = II()
    xs = []
    ys = []
    rs = []

    for _ in range(n):
        x, y, r = MII()
        xs.append(x)
        ys.append(y)
        rs.append(r)

    import time
    t = time.time()

    freq = 0
    total = 0

    while time.time() - t < 2.5:
        x = random.random() * 30 - 10
        y = random.random() * 30 - 10

        total += 1
        for i in range(n):
            vx = xs[i]
            vy = ys[i]
            r = rs[i]

            if (x - vx) * (x - vx) + (y - vy) * (y - vy) <= r * r:
                freq += 1
                break

    print(freq / total * 900)
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n;
	cin >> n;

	vector<array<int, 3>> circles(n);
	for (auto &[x, y, r]: circles) cin >> x >> y >> r;

	auto start = chrono::steady_clock::now();

	int freq = 0, total = 0;

	auto random_value = [&] () -> long double {
		auto val = rngl();
		long double ret = (long double)val / (1ull << 63) / 2;
		return ret;
	};

	while (true) {
		auto now = chrono::steady_clock::now();
		if (chrono::duration<double>(now - start).count() >= 2.5) break;

		double x = random_value() * 30 - 10;
		double y = random_value() * 30 - 10;
		total++;

		for (auto &[vx, vy, r]: circles) {
			if ((x - vx) * (x - vx) + (y - vy) * (y - vy) <= r * r) {
				freq ++; 
				break;
			}
		}
	}

	cout << fixed << setprecision(15) << (long double)freq / total * 900;

	return 0;
}
```

**提示 1：** 找清楚条件。

这里东南西北需要结合给出的样例确认，实则是上北下南左西右东。

两个条件：

- 到目标点的最短路长度是字符串的长度。

- 到目标点的最短路可以每一项都跟给定的方向不同。

所以我们先求到每个点的最短路。

接下来，假设我们求得了所有走 $k$ 步满足条件的位置，即最短路长度是 $k$ ，且前 $k$ 步可以完全不等于给定操作的可达位置。

接下来 $k+1$ 步的可行位置一定从这些位置出发。我们从这些位置出发，枚举三个非给定操作的方向，看对应的位置是否最短路长度为 $k+1$ ，如果是，将对应位置打上标记即可。

最后将所有步长为 $|s|$ 的标记位置记为答案即可。

时间复杂度为 $\mathcal{O}(nm+|s|)$ 。

### 具体代码如下——

Python 做法如下——

```Python []
def main():
    m, n = MII()
    tmp = [I() for _ in range(n)]
    ops = I()

    grid = [[0] * m for _ in range(n)]
    sx, sy = -1, -1

    for i in range(n):
        for j in range(m):
            if tmp[i][j] == '#': grid[i][j] = 1
            elif tmp[i][j] == 'S': sx, sy = i, j

    dis = [[-1] * m for _ in range(n)]

    def f(x, y): return x * m + y

    dis[sx][sy] = 0
    que = [f(sx, sy)]
    dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    for u in que:
        x, y = divmod(u, m)

        for dx, dy in dirs:
            if grid[x + dx][y + dy]: continue
            if dis[x + dx][y + dy] == -1:
                dis[x + dx][y + dy] = dis[x][y] + 1
                que.append(f(x + dx, y + dy))

    d = {
        'N': (-1, 0),
        'S': (1, 0),
        'W': (0, -1),
        'E': (0, 1)
    }

    l = len(ops)

    ans = [[0] * m for _ in range(n)]
    ans[sx][sy] = 1

    for u in que:
        x, y = divmod(u, m)

        if ans[x][y] and dis[x][y] < l:
            for c, (dx, dy) in d.items():
                if c != ops[dis[x][y]] and dis[x + dx][y + dy] == dis[x][y] + 1:
                    ans[x + dx][y + dy] = 1

    print('\n'.join(''.join(('!' if dis[i][j] == l and ans[i][j] else '.') if tmp[i][j] == '.' else tmp[i][j] for j in range(m)) for i in range(n)))
```

C++ 做法如下——

```cpp []
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n, m;
	cin >> m >> n;

	vector<string> grid(n);
	for (auto &v: grid) cin >> v;

	string ops;
	cin >> ops;

	int l = ops.size();

	int sx = -1, sy = -1;

	for (int i = 0; i < n; i ++) {
		for (int j = 0; j < m; j ++) {
			if (grid[i][j] == 'S') {
				sx = i, sy = j;
			}
		}
	}

	vector<pair<int, int>> que;
	vector<pair<int, int>> dirs = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};
	vector<vector<int>> dis(n, vector<int>(m, -1));

	que.emplace_back(sx, sy);
	dis[sx][sy] = 0;

	for (int i = 0; i < que.size(); i ++) {
		auto [x, y] = que[i];

		for (auto &[dx, dy]: dirs) {
			if (grid[x + dx][y + dy] == '#') continue;
			if (dis[x + dx][y + dy] == -1) {
				dis[x + dx][y + dy] = dis[x][y] + 1;
				que.emplace_back(x + dx, y + dy);
			}
		}
	}

	map<char, pair<int, int>> mp;
	mp['N'] = {-1, 0};
	mp['S'] = {1, 0};
	mp['W'] = {0, -1};
	mp['E'] = {0, 1};

	vector<vector<int>> ans(n, vector<int>(m, 0));
	ans[sx][sy] = 1;

	for (auto &[x, y]: que) {
		if (ans[x][y]) {
			if (dis[x][y] < l) {
				for (auto &[c, dir]: mp) {
					if (c != ops[dis[x][y]]) {
						auto [dx, dy] = dir;
						if (dis[x + dx][y + dy] == dis[x][y] + 1) {
							ans[x + dx][y + dy] = 1;
						}
					}
				}
			}
			else grid[x][y] = '!';
		}
	}

	for (auto &v: grid) cout << v << '\n';

	return 0;
}
```
